-- =============================================
-- 「ごめんの前に」のテーブルと初期データ
-- 最初にアクセスしたとき、common.php が自動で1回だけ実行する
-- =============================================

-- ユーザー
CREATE TABLE IF NOT EXISTS gomen_users (
  id             SERIAL       PRIMARY KEY,
  username       VARCHAR(30)  NOT NULL UNIQUE,
  password       VARCHAR(255) NOT NULL,
  remember_token CHAR(64)
);

-- 履歴（ユーザーがコピーした言い訳）
CREATE TABLE IF NOT EXISTS gomen_history (
  id         SERIAL      PRIMARY KEY,
  user_id    INTEGER     NOT NULL REFERENCES gomen_users(id) ON DELETE CASCADE,
  excuse_id  INTEGER     NOT NULL,
  answer     VARCHAR(20),
  created_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- 「ごめんの前に」言い訳データ（psql で \i excuses.sql を実行）
-- 相手4 × 要件6 × トーン3 × 各20個 = 1440個
CREATE TABLE IF NOT EXISTS gomen_excuses (
  id          SERIAL      PRIMARY KEY,
  aite        VARCHAR(20) NOT NULL,             -- 先生 / バイト先の店長 / 友達 / 家族
  youken      VARCHAR(20) NOT NULL,             -- 遅刻 / 課題の提出遅れ / 欠席 / 飲み会を断る / 既読スルー / 未読スルー
  tone        VARCHAR(10) NOT NULL,             -- 丁寧 / 普通 / ネタ
  excuse      TEXT        NOT NULL,             -- 言い訳の文
  bareta      INTEGER     NOT NULL DEFAULT 0,   -- 「バレた」と答えた人数
  barenakatta INTEGER     NOT NULL DEFAULT 0    -- 「バレなかった」と答えた人数
);

-- 遅刻 ／ 先生 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('先生', '遅刻', '丁寧', '先生におかれましては、平素より格別のご指導を賜り、心より御礼申し上げます。誠に申し上げにくいことではございますが、本日は電車が信号故障により運転を見合わせておりまして、到着が遅れてしまう見込みでございます。何卒ご容赦賜りますよう、伏してお願い申し上げます。', 1, 7),
('先生', '遅刻', '丁寧', '先生、朝早くから大変失礼いたします。誠に恐縮ではございますが、昨夜遅くまで課題に取り組んでおりましたところ、不覚にも寝過ごしてしまいました。授業に遅れてしまいますこと、心より深くお詫び申し上げます。', 5, 3),
('先生', '遅刻', '丁寧', '先生、誠に申し訳ございません。家を出る直前に体調が優れなくなり、少し休んでから向かっております。到着が遅れますこと、何卒お許しいただけますと幸いでございます。', 1, 9),
('先生', '遅刻', '丁寧', '先生におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、乗車しておりましたバスが事故渋滞に巻き込まれてしまいまして、授業の開始に間に合わない見込みでございます。心よりお詫び申し上げます。', 2, 8),
('先生', '遅刻', '丁寧', '先生、早朝より失礼いたします。大変恐縮ではございますが、台風の影響で電車が大幅に遅延しておりまして、到着が遅れてしまいます。何卒ご理解賜りますよう、お願い申し上げます。', 3, 7),
('先生', '遅刻', '丁寧', '先生、誠に申し訳ございません。通学途中に自転車がパンクしてしまいまして、徒歩にて向かっております。授業に遅れますこと、深くお詫び申し上げます。', 4, 5),
('先生', '遅刻', '丁寧', '先生におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に申し上げにくいのですが、病院の診察が予定より長引いておりまして、二限目からの出席となる見込みでございます。何卒ご容赦くださいませ。', 2, 10),
('先生', '遅刻', '丁寧', '先生、大変失礼いたします。乗り換えの際にホームを誤ってしまいまして、到着が十分ほど遅れてしまいます。私の不注意によりご迷惑をおかけしますこと、心よりお詫び申し上げます。', 6, 5),
('先生', '遅刻', '丁寧', '先生、誠に恐縮でございます。大雪により路線バスが運休となっておりまして、別の経路にて向かっております。到着が遅れますこと、何卒ご容赦賜りたく存じます。', 1, 9),
('先生', '遅刻', '丁寧', '先生におかれましては、平素より多大なるご指導を賜り、厚く御礼申し上げます。誠に恐れ入りますが、自宅の目覚まし時計の電池が切れておりまして、起床が遅れてしまいました。深く反省しております。', 5, 3),
('先生', '遅刻', '丁寧', '先生、誠に申し訳ございません。駅の改札が大変混雑しておりまして、予定の電車に乗ることができませんでした。授業に遅れますことを、心よりお詫び申し上げます。', 3, 6),
('先生', '遅刻', '丁寧', '先生、朝早くから恐れ入ります。祖父母の通院の付き添いを急きょ頼まれてしまいまして、到着が遅れる見込みでございます。何卒ご理解賜りますよう、お願い申し上げます。', 1, 7),
('先生', '遅刻', '丁寧', '先生におかれましては、日頃より温かいご指導を賜り、心より感謝申し上げます。大変申し上げにくいのですが、電車内で急病の方が出られた影響で停車しておりまして、到着が遅れてしまいます。', 3, 9),
('先生', '遅刻', '丁寧', '先生、誠に恐縮ではございますが、定期券を自宅に忘れてしまい、取りに戻っておりました。私の不徳の致すところでございます。到着が遅れますこと、深くお詫び申し上げます。', 5, 5),
('先生', '遅刻', '丁寧', '先生、大変申し訳ございません。強風により電車が徐行運転をしておりまして、授業の開始に間に合わない見込みでございます。何卒ご容赦賜りますよう、お願い申し上げます。', 2, 8),
('先生', '遅刻', '丁寧', '先生におかれましては、ますますご健勝のこととお慶び申し上げます。誠に恐れ入りますが、朝から腹痛がひどく、薬が効くのを待っておりました。少々遅れて伺いますこと、お許しくださいませ。', 5, 5),
('先生', '遅刻', '丁寧', '先生、誠に申し訳ございません。役所での手続きが予想以上に長引いてしまいまして、到着が遅れてしまう見込みでございます。重ねてお詫び申し上げます。', 3, 8),
('先生', '遅刻', '丁寧', '先生、早朝より大変失礼いたします。踏切で長時間足止めをされておりまして、授業に遅れてしまいます。ご迷惑をおかけしますこと、心よりお詫び申し上げます。', 6, 3),
('先生', '遅刻', '丁寧', '先生におかれましては、平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ながら、集合時間を一本勘違いしておりまして、到着が遅れてしまいました。猛省しております。', 8, 4),
('先生', '遅刻', '丁寧', '先生、誠に申し訳ございません。道路が凍結しておりまして、転倒しないよう慎重に歩いておりましたところ、到着が遅れてしまいます。何卒ご容赦くださいませ。', 2, 9);

