-- 遅刻 ／ バイト先の店長 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('バイト先の店長', '遅刻', '丁寧', '店長におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、電車が信号故障により遅延しておりまして、シフトの開始時刻に間に合わない見込みでございます。多大なるご迷惑をおかけしますこと、心より深くお詫び申し上げます。', 6, 5),
('バイト先の店長', '遅刻', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、乗車しておりましたバスが渋滞に巻き込まれてしまいまして、十五分ほど遅れて到着いたします。皆様にご迷惑をおかけし、大変申し訳ございません。', 5, 5),
('バイト先の店長', '遅刻', '丁寧', '店長におかれましては、平素より格別のご配慮を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、寝過ごしてしまいまして、出勤が遅れてしまう見込みでございます。深く反省しております。', 7, 3),
('バイト先の店長', '遅刻', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、自転車がパンクしてしまいまして、徒歩にて向かっております。到着が遅れますこと、何卒ご容赦くださいませ。', 3, 9),
('バイト先の店長', '遅刻', '丁寧', '店長、誠に申し訳ございません。前の授業が予定より長引いてしまいまして、シフトに少々遅れてしまいます。ご迷惑をおかけしますこと、心よりお詫び申し上げます。', 6, 6),
('バイト先の店長', '遅刻', '丁寧', '店長におかれましては、日頃より温かいご指導を賜り、心より感謝申し上げます。誠に恐れ入りますが、大雪により電車の運行が乱れておりまして、出勤が遅れてしまいます。', 1, 9),
('バイト先の店長', '遅刻', '丁寧', '店長、お疲れさまでございます。誠に恐縮でございますが、家族の送迎を急きょ頼まれてしまいまして、到着が遅れる見込みでございます。何卒ご理解賜りますよう、お願い申し上げます。', 1, 7),
('バイト先の店長', '遅刻', '丁寧', '店長、大変申し訳ございません。乗り換えを誤ってしまいまして、到着が十分ほど遅れてしまいます。私の不注意によりご迷惑をおかけしますこと、深くお詫び申し上げます。', 5, 5),
('バイト先の店長', '遅刻', '丁寧', '店長におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に申し上げにくいのですが、体調が優れず少し休んでから向かっております。遅れて出勤いたしますこと、お許しくださいませ。', 3, 8),
('バイト先の店長', '遅刻', '丁寧', '店長、お疲れさまでございます。強風により電車が徐行運転をしておりまして、シフトの開始に間に合わない見込みでございます。何卒ご容赦賜りますよう、お願い申し上げます。', 1, 7),
('バイト先の店長', '遅刻', '丁寧', '店長、誠に恐縮ではございますが、制服を自宅に忘れてしまいまして、取りに戻っております。到着が遅れますこと、心よりお詫び申し上げます。', 5, 3),
('バイト先の店長', '遅刻', '丁寧', '店長におかれましては、平素より大変お世話になっております。誠に恐れ入りますが、病院の診察が長引いておりまして、出勤が遅れてしまう見込みでございます。', 2, 10),
('バイト先の店長', '遅刻', '丁寧', '店長、大変申し訳ございません。踏切で長時間足止めをされておりまして、シフトに遅れてしまいます。皆様にご迷惑をおかけし、誠に申し訳ございません。', 4, 8),
('バイト先の店長', '遅刻', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、シフトの開始時刻を一時間勘違いしておりました。只今全力で向かっております。猛省しております。', 5, 5),
('バイト先の店長', '遅刻', '丁寧', '店長におかれましては、日頃より格別のご高配を賜り、厚く御礼申し上げます。誠に恐れ入りますが、台風の影響でバスが大幅に遅れておりまして、到着が遅れてしまいます。', 1, 7),
('バイト先の店長', '遅刻', '丁寧', '店長、誠に申し訳ございません。駐輪場が満車でございまして、停める場所を探しておりました。到着が数分遅れますこと、何卒お許しくださいませ。', 3, 6),
('バイト先の店長', '遅刻', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、電車内で急病の方が出られた影響で停車しておりまして、出勤が遅れてしまいます。', 2, 10),
