('バイト先の店長', '遅刻', 'ネタ', '店長、制服を着て出たつもりが、パジャマでした。着替えに戻っています。', 7, 1),
('バイト先の店長', '遅刻', 'ネタ', '店長、目覚まし時計がストライキを起こしていました。遅れます。', 9, 2),
('バイト先の店長', '遅刻', 'ネタ', '店長、朝の占いで「今日は急ぐと運気が下がる」と出たので、ゆっくり向かっています。', 7, 2),
('バイト先の店長', '遅刻', 'ネタ', '店長、駅で迷子のカメを池まで送り届けていました。遅れます。', 7, 2),
