('バイト先の店長', '遅刻', 'ネタ', '店長、近所の人の世間話が三周目に入りました。抜け出せたら行きます。', 8, 3),
('バイト先の店長', '遅刻', 'ネタ', '店長、自転車をこいでいたら気持ちよすぎて、バイト先を通り過ぎていました。', 7, 2),
('バイト先の店長', '遅刻', 'ネタ', '店長、くしゃみが止まらなくて、十回出るまで待っていました。遅れます。', 11, 1),
('バイト先の店長', '遅刻', 'ネタ', '店長、今日は休みだと信じて二度寝していました。今、現実を知りました。', 6, 2),
('バイト先の店長', '遅刻', 'ネタ', '店長、鳩の群れに道をふさがれていました。説得に成功したので向かいます。', 9, 3),
('バイト先の店長', '遅刻', 'ネタ', '店長、カバンの中でイヤホンが絡まりすぎて、ほどくのに時間がかかりました。', 8, 3),
('バイト先の店長', '遅刻', 'ネタ', '店長、朝ごはんを作りすぎて、食べきるまで家を出られませんでした。', 9, 3),
