('バイト先の店長', '遅刻', 'ネタ', '店長、知らないお祭りに巻き込まれて、神輿を担いでいました。遅れます。', 9, 3),
('バイト先の店長', '遅刻', 'ネタ', '店長、ペットに「行かないで」と見つめられて、心が折れそうになっていました。', 8, 3),
