-- 遅刻 ／ 友達 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('友達', '遅刻', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、電車が遅延しておりまして、お約束の時刻に十分ほど遅れてしまう見込みでございます。心より深くお詫び申し上げます。', 1, 9),
('友達', '遅刻', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に申し上げにくいのですが、不覚にも寝過ごしてしまいまして、待ち合わせに遅れてしまいます。今後とも変わらぬご厚誼を賜りますよう、お願い申し上げます。', 5, 3),
('友達', '遅刻', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、心より感謝申し上げます。誠に恐れ入りますが、バスが渋滞に巻き込まれておりまして、到着が遅れてしまいます。何卒ご容赦くださいませ。', 1, 8),
('友達', '遅刻', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ながら、家を出る直前に財布を忘れたことに気づき、取りに戻っております。深くお詫び申し上げます。', 7, 4),
('友達', '遅刻', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、乗り換えを誤ってしまいまして、到着が遅れる見込みでございます。私の不注意を、何卒お許しくださいませ。', 3, 5),
('友達', '遅刻', '丁寧', '親愛なる友へ。誠に申し訳ございません。待ち合わせ場所を一駅勘違いしておりまして、只今そちらへ向かっております。多大なるご迷惑をおかけし、心よりお詫び申し上げます。', 7, 3),
('友達', '遅刻', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、自転車がパンクしてしまいまして、到着が遅れてしまいます。ご容赦賜りますよう、お願い申し上げます。', 3, 8),
('友達', '遅刻', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐縮ではございますが、前の用事が長引いておりまして、お約束の時刻に間に合わない見込みでございます。深くお詫び申し上げます。', 3, 6),
('友達', '遅刻', '丁寧', '親愛なる友へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、身支度に想定以上の時間を要しておりまして、到着が遅れてしまいます。', 5, 7),
('友達', '遅刻', '丁寧', '親愛なる友へ。誠に恐縮ではございますが、大雪により電車の運行が乱れておりまして、待ち合わせに遅れてしまう見込みでございます。何卒ご理解賜りますよう、お願い申し上げます。', 2, 8),
('友達', '遅刻', '丁寧', '親愛なる友へ。平素より大変お世話になっております。誠に恐れ入りますが、家族の用事を急きょ頼まれてしまいまして、到着が遅れてしまいます。重ねてお詫び申し上げます。', 2, 7),
('友達', '遅刻', '丁寧', '親愛なる友へ。いつも格別のお心遣いを賜り、厚く御礼申し上げます。大変恐縮ながら、降りる駅を乗り過ごしてしまいまして、只今引き返しております。心よりお詫び申し上げます。', 5, 5),
('友達', '遅刻', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に恐縮でございますが、スマートフォンの地図の案内が誤っておりまして、道に迷っております。到着が遅れますこと、お許しくださいませ。', 8, 3),
('友達', '遅刻', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、心より御礼申し上げます。誠に申し上げにくいのですが、駅の改札が大変混雑しておりまして、予定の電車に乗り損ねてしまいました。', 3, 5),
('友達', '遅刻', '丁寧', '親愛なる友へ。誠に恐れ入りますが、強風により電車が徐行運転をしておりまして、お約束の時刻に遅れてしまいます。何卒ご容赦賜りますよう、伏してお願い申し上げます。', 2, 6),
('友達', '遅刻', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、厚く御礼申し上げます。誠に恐縮ながら、コンタクトレンズを落としてしまいまして、探しておりました。到着が遅れますことをお詫び申し上げます。', 5, 7),
('友達', '遅刻', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、鍵が見つからず家を出るのが遅れてしまいました。心より深くお詫び申し上げます。', 4, 7),
('友達', '遅刻', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、タクシーがなかなかつかまらず、到着が遅れてしまう見込みでございます。', 4, 6),
('友達', '遅刻', '丁寧', '親愛なる友へ。誠に申し訳ございません。台風の影響でバスが大幅に遅れておりまして、待ち合わせに間に合いそうにございません。今後とも末永くよろしくお願い申し上げます。', 2, 9),
('友達', '遅刻', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐れ入りますが、電車内で急病の方が出られた影響で停車しておりまして、到着が遅れてしまいます。何卒ご容赦くださいませ。', 2, 6);

