('友達', '遅刻', 'ネタ', 'ちょっと聞いて。寝ぐせが芸術的すぎて、直すのに時間かかった。', 9, 2),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。靴を左右逆に履いて出てて、途中で気づいて戻ってる。', 9, 2),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。夢の中ではもう着いてて、安心して二度寝した。', 9, 2),
