('友達', '遅刻', 'ネタ', 'ちょっと聞いて。知らない人に道を聞かれて一緒に迷ってる。', 10, 2),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。虹が出てて写真撮ってたら電車が行っちゃった。', 8, 2),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。くしゃみが十回連続で出て動けなかった。', 6, 3),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。服を選んでたらファッションショーが始まってた。', 10, 1),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。昨日の自分にアラームを任せたら裏切られた。', 10, 1),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。近所の犬に気に入られてついて来られた。家に送り届けてる。', 7, 1),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。家を出たら雨で、戻ったら晴れて、出たらまた雨だった。', 7, 1),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。待ち合わせの時間、時計の針を一周間違えて読んでた。', 10, 1),
('友達', '遅刻', 'ネタ', 'ちょっと聞いて。冷蔵庫を開けたらプリンと目が合って、食べてから出た。', 6, 2),
