('友達', '遅刻', 'ネタ', 'ちょっと聞いて。今日が約束の日じゃない世界線にいた気がする。', 5, 3);

-- 遅刻 ／ 家族 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ではございますが、授業が予定より長引いてしまいまして、帰宅が遅れてしまう見込みでございます。心より深くお詫び申し上げます。', 2, 7),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、電車が遅延しておりまして、夕食の時間に間に合わない見込みでございます。', 2, 7),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。いつも温かく見守っていただき、心より感謝申し上げます。誠に恐れ入りますが、アルバイトが長引いてしまいまして、帰宅が遅くなってしまいます。何卒ご容赦くださいませ。', 2, 10),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ながら、お約束の待ち合わせ時刻に十分ほど遅れてしまう見込みでございます。今後とも末永くよろしくお願い申し上げます。', 2, 9),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご配慮を賜り、厚く御礼申し上げます。大変恐れ入りますが、部活動の片付けが長引いておりまして、帰宅が遅れてしまいます。', 1, 7),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。バスが渋滞に巻き込まれておりまして、門限に間に合わない見込みでございます。心より深くお詫び申し上げます。', 2, 8),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮でございますが、図書館で課題に集中しておりまして、時間を失念してしまいました。帰宅が遅れますこと、お許しくださいませ。', 3, 9),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、友人との用事が長引いてしまいまして、帰宅が遅くなってしまいます。', 2, 7),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。大変恐縮ではございますが、乗り換えを誤ってしまいまして、到着が遅れる見込みでございます。何卒ご容赦賜りますよう、お願い申し上げます。', 2, 7),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。誠に恐れ入りますが、大雪により電車の運行が乱れておりまして、帰宅が遅れてしまいます。夕食は先にお召し上がりくださいませ。', 2, 7),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、自転車がパンクしてしまいまして、徒歩にて帰宅しております。', 3, 9),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。平素より大変お世話になっております。誠に恐縮ながら、学校で先生に質問をしておりましたところ、帰りが遅くなってしまいました。深くお詫び申し上げます。', 1, 7),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。降りる駅を乗り過ごしてしまいまして、只今引き返しております。帰宅が遅れますこと、心よりお詫び申し上げます。', 6, 6),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。いつも温かいお心遣いを賜り、厚く御礼申し上げます。大変恐れ入りますが、強風により電車が徐行運転をしておりまして、帰宅が遅れてしまいます。', 3, 8),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ではございますが、委員会の仕事が終わらず、帰宅が遅くなってしまう見込みでございます。', 2, 10),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、研究室の作業が長引いておりまして、夕食の時間に遅れてしまいます。', 2, 6),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。台風の影響でバスが大幅に遅れておりまして、帰宅が遅れる見込みでございます。何卒ご理解賜りますよう、お願い申し上げます。', 2, 10),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。誠に恐縮でございますが、スマートフォンの充電が切れてしまい、ご連絡が遅れたうえに帰宅も遅くなってしまいました。', 4, 8),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。日頃より格別のご高配を賜り、心より御礼申し上げます。誠に申し上げにくいのですが、電車内で急病の方が出られた影響で停車しておりまして、帰宅が遅れてしまいます。', 2, 8),
('家族', '遅刻', '丁寧', '敬愛するご家族の皆様へ。平素より大変お世話になっております。誠に恐縮ながら、買い物を頼まれた品がなかなか見つからず、帰宅が遅れてしまいます。今後とも末永くよろしくお願い申し上げます。', 3, 9);

