-- 遅刻 ／ 家族 ／ ネタ
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。帰り道で猫に見つめられて動けなくなってた。遅くなる。', 9, 3),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。夕日がきれいすぎて見とれてたら日が暮れてた。', 9, 0),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。帰り道で知らないお祭りに巻き込まれて、盆踊りを踊ってた。', 7, 1),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。電車で寝てたら、終点で知らない景色を見てた。', 8, 3),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。コンビニの新作スイーツを全部見比べてた。遅くなる。', 9, 3),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。帰り道で迷子のカメを池まで送り届けてた。', 10, 2),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。鳩の群れに帰り道をふさがれてる。説得中。', 9, 0),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。夕飯のメニューを予想してたら、反対方向の電車に乗ってた。', 8, 4),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。帰る途中で自分探しの旅が始まっちゃった。', 11, 1),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。空に流れ星が見えた気がして、ずっと待ってた。', 9, 1),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。近所の犬に気に入られて、一緒にお散歩してた。', 10, 2),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。くしゃみが十回連続で出て、立ち止まってた。', 10, 1),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。家の前まで来たけど、鍵がカバンの中で迷子になってる。', 9, 1),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。帰り道の自販機で当たりが出て、もう一本選ぶのに悩んでた。', 9, 2),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。駅で四つ葉のクローバーを探してたら暗くなった。', 8, 1),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。家に帰る道を一本間違えて、新しい道を開拓してた。', 7, 2),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。帰る前に寄った本屋で、気づいたら立ち読み三冊目だった。', 7, 3),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。電車の窓から見えた雲が面白い形で、ずっと見てた。', 7, 3),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。家の近くで近所の人の世間話が三周目に入った。', 6, 2),
('家族', '遅刻', 'ネタ', 'ちょっと聞いて。帰る気満々だったのに、足が勝手に寄り道してた。', 8, 3);

-- 課題の提出遅れ ／ 先生 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('先生', '課題の提出遅れ', '丁寧', '先生におかれましては、平素より格別のご指導を賜り、心より御礼申し上げます。誠に申し上げにくいことではございますが、提出直前にパソコンが故障してしまいまして、課題の提出が期限に間に合わない見込みでございます。何卒ご容赦賜りますよう、伏してお願い申し上げます。', 5, 5),
('先生', '課題の提出遅れ', '丁寧', '先生、大変失礼いたします。誠に恐縮ではございますが、保存したつもりのファイルが古い版のままでございまして、只今最新版を作り直しております。提出が遅れますこと、心より深くお詫び申し上げます。', 6, 3),
('先生', '課題の提出遅れ', '丁寧', '先生におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、体調を崩して数日寝込んでおりまして、課題の提出が遅れてしまいます。何卒ご理解賜りますよう、お願い申し上げます。', 2, 8),
('先生', '課題の提出遅れ', '丁寧', '先生、誠に申し訳ございません。締め切りの日付を一日勘違いしておりまして、提出が遅れてしまいました。私の不注意によりご迷惑をおかけしますこと、深くお詫び申し上げます。', 6, 6),
('先生', '課題の提出遅れ', '丁寧', '先生におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に申し上げにくいのですが、実験データに不備が見つかりまして、取り直しを行っております。提出期限の延長をお願いできますでしょうか。', 3, 6),
('先生', '課題の提出遅れ', '丁寧', '先生、大変恐縮でございます。提出システムに不具合があるようでございまして、何度試してもアップロードができません。メールにて提出させていただいてもよろしいでしょうか。', 6, 4),
('先生', '課題の提出遅れ', '丁寧', '先生、誠に恐れ入ります。グループのメンバーと連絡がつかず、担当部分がそろっておりません。提出が遅れますこと、何卒ご容赦くださいませ。', 4, 6),
('先生', '課題の提出遅れ', '丁寧', '先生におかれましては、平素より温かいご指導を賜り、心より感謝申し上げます。誠に恐縮ながら、課題の内容を読み違えておりまして、只今最初から取り組み直しております。深く反省しております。', 3, 5),
('先生', '課題の提出遅れ', '丁寧', '先生、早朝より失礼いたします。自宅のインターネット回線が故障しておりまして、課題を提出することができませんでした。復旧次第すぐに提出いたします。', 5, 3),
('先生', '課題の提出遅れ', '丁寧', '先生、誠に申し訳ございません。プリンターが故障してしまいまして、レポートを印刷することができませんでした。明日の朝一番に提出させていただきたく存じます。', 3, 5),
('先生', '課題の提出遅れ', '丁寧', '先生におかれましては、日頃より格別のご高配を賜り、厚く御礼申し上げます。誠に恐れ入りますが、必要な参考文献が図書館で貸し出し中でございまして、調査が終わっておりません。', 3, 9),
('先生', '課題の提出遅れ', '丁寧', '先生、大変失礼いたします。添付ファイルを付け忘れたまま送信してしまいました。改めてお送りいたしますので、何卒ご確認賜りますようお願い申し上げます。', 7, 4),
('先生', '課題の提出遅れ', '丁寧', '先生、誠に恐縮でございます。家族の看病をしておりまして、課題に取り組む時間が十分に取れませんでした。提出が遅れますこと、心よりお詫び申し上げます。', 3, 7),
('先生', '課題の提出遅れ', '丁寧', '先生におかれましては、平素より多大なるご指導を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、プログラムのエラーがどうしても解決できず、提出が遅れてしまう見込みでございます。', 5, 4),
('先生', '課題の提出遅れ', '丁寧', '先生、大変申し訳ございません。課題が出ていたことを見落としておりまして、只今急いで取り組んでおります。猛省しております。', 6, 4),
('先生', '課題の提出遅れ', '丁寧', '先生、誠に恐れ入りますが、就職活動の面接と締め切りが重なってしまいまして、課題を仕上げることができませんでした。何卒ご容赦賜りますよう、お願い申し上げます。', 1, 9),
('先生', '課題の提出遅れ', '丁寧', '先生におかれましては、ますますご健勝のこととお慶び申し上げます。誠に恐縮ながら、作業中にソフトが強制終了してしまいまして、データの一部が失われてしまいました。', 4, 7),
('先生', '課題の提出遅れ', '丁寧', '先生、大変失礼いたします。ファイルの容量が大きすぎて送信できない状態でございます。分割して提出させていただいてもよろしいでしょうか。', 4, 6),
('先生', '課題の提出遅れ', '丁寧', '先生、誠に申し訳ございません。停電によりパソコンの電源が落ちてしまいまして、作業途中のデータが消えてしまいました。提出が遅れますこと、深くお詫び申し上げます。', 6, 4),
('先生', '課題の提出遅れ', '丁寧', '先生におかれましては、平素より格別のご配慮を賜り、心より感謝申し上げます。誠に恐れ入りますが、内容にこだわるあまり時間配分を誤ってしまいました。もう一日だけお時間を頂戴できますと幸いでございます。', 4, 7);

