('先生', '課題の提出遅れ', '普通', '先生、実験データを取り直していて、提出を少し待っていただけますか。', 3, 7),
('先生', '課題の提出遅れ', '普通', '先生、提出システムにアップロードできません。メールで送ってもいいですか。', 4, 8),
('先生', '課題の提出遅れ', '普通', '先生、グループの人と連絡がつかなくて、まだそろっていません。すみません。', 3, 6),
('先生', '課題の提出遅れ', '普通', '先生、課題の内容を読み違えていて、やり直しています。少し遅れます。', 4, 7),
('先生', '課題の提出遅れ', '普通', '先生、家のネットがつながらなくて提出できませんでした。直り次第出します。', 5, 3),
('先生', '課題の提出遅れ', '普通', '先生、プリンターが壊れて印刷できませんでした。明日の朝に出します。', 3, 7),
('先生', '課題の提出遅れ', '普通', '先生、参考文献が貸し出し中で、まだ調べきれていません。すみません。', 4, 8),
('先生', '課題の提出遅れ', '普通', '先生、ファイルを添付し忘れていました。もう一度送ります。', 6, 5),
('先生', '課題の提出遅れ', '普通', '先生、家族の看病で時間が取れませんでした。少し遅れて出します。', 3, 9),
('先生', '課題の提出遅れ', '普通', '先生、プログラムのエラーが直らなくて、提出が遅れそうです。', 6, 3),
('先生', '課題の提出遅れ', '普通', '先生、課題が出ていたのを見落としていました。急いでやります。', 5, 4),
('先生', '課題の提出遅れ', '普通', '先生、面接と締め切りが重なってしまって、間に合いませんでした。すみません。', 1, 7),
('先生', '課題の提出遅れ', '普通', '先生、ソフトが落ちてデータが一部消えてしまいました。作り直しています。', 7, 5),
('先生', '課題の提出遅れ', '普通', '先生、ファイルが大きすぎて送れません。分けて送ってもいいですか。', 3, 5),
('先生', '課題の提出遅れ', '普通', '先生、停電でパソコンが落ちて、データが消えてしまいました。すみません。', 6, 6),
('先生', '課題の提出遅れ', '普通', '先生、時間配分を間違えてしまいました。あと一日だけ待っていただけますか。', 3, 7);

-- 課題の提出遅れ ／ 先生 ／ ネタ
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('先生', '課題の提出遅れ', 'ネタ', '先生、聞いてください。課題を書いていたら壮大な小説になってしまい、完結まであと三章あります。', 6, 2),
('先生', '課題の提出遅れ', 'ネタ', '先生、猫がキーボードの上で寝てしまい、どかすのは失礼だと思って待っていました。', 10, 2),
('先生', '課題の提出遅れ', 'ネタ', '先生、課題が完璧すぎて、提出するのがもったいなくなりました。', 10, 1),
('先生', '課題の提出遅れ', 'ネタ', '先生、夢の中では提出していて、満足して起きました。', 8, 4),
('先生', '課題の提出遅れ', 'ネタ', '先生、保存ボタンと削除ボタンを、勇気を持って見間違えました。', 9, 3),
('先生', '課題の提出遅れ', 'ネタ', '先生、パソコンがアップデートの旅に出て、まだ帰ってきません。', 10, 1),
('先生', '課題の提出遅れ', 'ネタ', '先生、ファイル名を「最終版」「本当の最終版」「最終版2」にしていたら、どれが最終版かわからなくなりました。', 8, 2),
('先生', '課題の提出遅れ', 'ネタ', '先生、フォント選びで三時間悩んで、本文に手が回りませんでした。', 6, 2),
('先生', '課題の提出遅れ', 'ネタ', '先生、締め切りという概念について深く考えていたら、締め切りが過ぎていました。', 8, 2),
('先生', '課題の提出遅れ', 'ネタ', '先生、提出ボタンを押す勇気が、まだ出ません。', 9, 1),
('先生', '課題の提出遅れ', 'ネタ', '先生、誤字を探していたら、新しい誤字を三つ生み出していました。', 10, 1),
('先生', '課題の提出遅れ', 'ネタ', '先生、参考文献を読んでいたら別の分野に興味が移って、そっちを極めていました。', 8, 0),
('先生', '課題の提出遅れ', 'ネタ', '先生、やる気が出るのを待っていたら、締め切りが先に来ました。', 9, 1),
('先生', '課題の提出遅れ', 'ネタ', '先生、犬に課題を見せたら気に入られて、返してもらえません。', 9, 2),
('先生', '課題の提出遅れ', 'ネタ', '先生、机の片付けから始めたら、部屋の大掃除で一日が終わりました。', 10, 2),
('先生', '課題の提出遅れ', 'ネタ', '先生、作業用の音楽を選んでいたら朝になっていました。', 8, 3),
('先生', '課題の提出遅れ', 'ネタ', '先生、プリンターと心が通じ合わず、印刷を拒否されています。', 10, 1),
('先生', '課題の提出遅れ', 'ネタ', '先生、完成した喜びで踊っていたら、保存するのを忘れていました。', 7, 2),
('先生', '課題の提出遅れ', 'ネタ', '先生、天才的なひらめきが降りてくるのを待っています。もう少しで来ると思います。', 6, 2),
('先生', '課題の提出遅れ', 'ネタ', '先生、提出日を来週だと信じていました。信じる心は大切だと思います。', 8, 3);

-- 課題の提出遅れ ／ バイト先の店長 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、シフト希望表の提出が遅れてしまいまして、深くお詫び申し上げます。本日中に必ず提出いたします。', 1, 10),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、提出を求められておりました銀行口座の書類を自宅に忘れてしまいました。明日には必ずお持ちいたします。', 5, 3),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長におかれましては、平素より格別のご配慮を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、テスト期間と重なってしまいまして、シフト希望の提出が遅れております。', 2, 7),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、誠に申し訳ございません。研修のレポートを作成しておりましたところ、ファイルが消えてしまいまして、只今作り直しております。提出が遅れますこと、心よりお詫び申し上げます。', 4, 4),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、学校の予定がまだ確定しておりませんで、シフト希望表を出せずにおります。何卒今しばらくお待ちいただけますと幸いでございます。', 1, 8),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長におかれましては、日頃より温かいご指導を賜り、心より感謝申し上げます。誠に恐れ入りますが、住民票の取得に手間取っておりまして、書類の提出が遅れてしまいます。', 4, 5),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、誠に恐縮でございます。在庫確認の報告書を作成しておりましたところ、数字が合わず確認し直しております。正確なものをお出しするため、今しばらくお時間を頂戴いたします。', 5, 7),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、提出期限を一週間勘違いしておりました。私の不注意によりご迷惑をおかけし、深くお詫び申し上げます。', 6, 5),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に恐れ入りますが、体調を崩しておりまして、提出物の準備が遅れております。何卒ご容赦くださいませ。', 2, 9),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、大変申し訳ございません。マイナンバーの書類の写しを取り忘れておりまして、提出が遅れてしまいます。明日の出勤時に必ずお持ちいたします。', 4, 4),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、シフト希望表をお店に置き忘れてしまいまして、記入ができておりません。次回の出勤時に記入いたします。', 4, 4),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長におかれましては、平素より多大なるご配慮を賜り、厚く御礼申し上げます。誠に恐れ入りますが、家族の都合が確認できておりませんで、長期休暇のシフト希望が出せずにおります。', 2, 10),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、誠に申し訳ございません。アンケートの集計を担当しておりましたところ、思った以上に時間がかかっております。完成まで今しばらくお待ちくださいませ。', 3, 6),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、自宅のプリンターが故障してしまいまして、書類を印刷できませんでした。お店で印刷させていただいてもよろしいでしょうか。', 4, 5),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長におかれましては、日頃より格別のご高配を賜り、心より感謝申し上げます。誠に恐縮ではございますが、保護者の同意書に署名をもらう機会がなく、提出が遅れております。', 3, 5),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、誠に恐縮でございます。研修動画の視聴課題を、通信制限のため最後まで見ることができませんでした。本日中に必ず完了いたします。', 1, 7),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、提出する書類の書き方がわからず、確認しておりました。遅れましたことを深くお詫び申し上げます。', 3, 8),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長におかれましては、平素より大変お世話になっております。誠に恐れ入りますが、写真付きの身分証明書の更新手続き中でございまして、写しの提出が遅れてしまいます。', 2, 7),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、大変申し訳ございません。メールで送信したつもりが、送信エラーになっておりました。改めてお送りいたしますので、ご確認をお願い申し上げます。', 8, 4),
('バイト先の店長', '課題の提出遅れ', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、学校の課題の締め切りが重なっておりまして、提出物が遅れてしまいました。心よりお詫び申し上げます。', 5, 7);

-- 課題の提出遅れ ／ バイト先の店長 ／ 普通
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。シフト希望表の提出が遅れてすみません。今日中に出します。', 2, 9),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。口座の書類を家に忘れてしまいました。明日持ってきます。', 7, 4),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。テスト期間と重なってシフト希望が遅れています。すみません。', 1, 8),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。研修レポートのファイルが消えてしまって、作り直しています。', 4, 4),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。学校の予定がまだ決まっていなくて、シフト希望が出せていません。', 1, 7),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。住民票を取るのに手間取っていて、書類が遅れそうです。', 5, 7),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。在庫報告の数字が合わなくて確認し直しています。少し待ってください。', 3, 5),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。提出期限を一週間勘違いしていました。すみません。', 6, 4),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。体調を崩していて、提出物の準備が遅れています。', 2, 7),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。書類のコピーを取り忘れていました。明日持ってきます。', 5, 3),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。シフト表をお店に置き忘れていました。次の出勤のときに書きます。', 4, 6),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。家族の予定がまだわからなくて、休み中のシフトが出せていません。', 2, 8),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。アンケートの集計に時間がかかっています。もう少し待ってください。', 4, 8),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。家のプリンターが壊れてしまって、お店で印刷してもいいですか。', 3, 7),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。親のサインをもらえていなくて、同意書がまだです。すみません。', 5, 7),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。通信制限で研修動画が最後まで見られていません。今日中に見ます。', 3, 9),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。書類の書き方がわからなくて確認していました。遅れてすみません。', 4, 8),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。身分証の更新中で、コピーを出すのが遅れます。', 4, 6),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。メールが送信エラーになっていました。もう一度送ります。', 7, 4),
('バイト先の店長', '課題の提出遅れ', '普通', 'お疲れさまです。学校の課題と重なってしまって、提出が遅れました。すみません。', 5, 6);

-- 課題の提出遅れ ／ バイト先の店長 ／ ネタ
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、聞いてください。シフト希望表を書いていたら、未来の自分の予定が見えなくなりました。', 7, 3),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、シフト希望表を冷蔵庫にしまっていました。今、冷えています。', 11, 1),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、書類を書こうとしたらペンが全部インク切れで、ペン探しの旅に出ていました。', 6, 2),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、提出しようとしたら、書類が風に乗って飛んでいきました。追いかけています。', 8, 1),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、猫が書類の上で寝ていて、起こすのはかわいそうだったので待っていました。', 9, 2),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、シフト希望を考えすぎて、自分が何曜日に生きているのかわからなくなりました。', 7, 2),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、報告書を書いていたら感動的な物語になってしまい、まだ泣いています。', 6, 2),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、書類のハンコを押す位置で三十分迷っていました。', 7, 1),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、口座の書類を持ってきたつもりが、カバンの中で行方不明です。', 6, 2),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、休みの希望日を全部書いたら、全部休みになってしまったので書き直しています。', 8, 1),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、提出物の存在を、前向きに忘れていました。', 10, 2),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、書類を書いている途中で寝てしまい、よだれで文字がにじみました。', 10, 1),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、提出期限を「来世」と読み間違えていました。', 7, 1),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、シフト表の空欄を見ていたら、宇宙の広さについて考え始めてしまいました。', 9, 3),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、書類を犬に見せたら気に入って、離してくれません。', 6, 3),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、記入した書類を大事にしまいすぎて、どこにしまったか忘れました。', 7, 1),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、シフト希望を占いで決めようとしたら、全部「大凶」でした。', 9, 1),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、書類を書く前の準備運動が長引いています。', 8, 2),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、書類の写真を撮ろうとしたら、ピントが合うまで一時間かかりました。', 7, 3),
('バイト先の店長', '課題の提出遅れ', 'ネタ', '店長、提出物のことを考えすぎて、夢にまで出てきて寝不足です。', 9, 1);

-- 課題の提出遅れ ／ 友達 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、お願いされておりましたノートの写しの準備が遅れておりまして、明日にお渡しする見込みでございます。心より深くお詫び申し上げます。', 3, 6),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に申し上げにくいのですが、共同課題の私の担当部分がまだ完成しておりません。今夜中に必ず仕上げてお送りいたします。', 5, 6),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、心より感謝申し上げます。誠に恐れ入りますが、パソコンが故障してしまいまして、スライドの作成が遅れてしまいます。何卒ご容赦くださいませ。', 4, 4),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ながら、まとめを頼まれていた資料のファイルを上書きしてしまいまして、作り直しております。', 6, 5),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、アルバイトが立て込んでおりまして、担当部分の調べものが終わっておりません。今しばらくお待ちくださいませ。', 3, 8),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。誠に申し訳ございません。共有フォルダへのアップロードを失念しておりました。只今アップロードいたしましたので、ご確認をお願い申し上げます。', 3, 8),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、体調を崩して寝込んでおりまして、発表原稿の作成が遅れております。', 2, 9),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐縮ではございますが、締め切りを一日勘違いしておりまして、担当部分が間に合いませんでした。深くお詫び申し上げます。', 8, 3),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、グラフの作成に手間取っておりまして、完成まで今しばらくお時間を頂戴いたします。', 3, 7),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。誠に恐縮ではございますが、自宅のインターネットがつながらず、ファイルをお送りすることができませんでした。明朝、学校にてお渡しいたします。', 5, 5),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。平素より大変お世話になっております。誠に恐れ入りますが、家族の用事で時間が取れず、作業が遅れてしまいました。今後とも変わらぬご厚誼を賜りますよう、お願い申し上げます。', 1, 9),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。いつも格別のお心遣いを賜り、厚く御礼申し上げます。大変恐縮ながら、参考資料が見つからず、調査が終わっておりません。何卒ご容赦くださいませ。', 4, 7),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に恐縮でございますが、作業中に寝落ちしてしまいまして、気づいたら朝でございました。心よりお詫び申し上げます。', 7, 5),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、心より御礼申し上げます。誠に申し上げにくいのですが、ソフトが強制終了いたしまして、編集中の動画が消えてしまいました。', 6, 4),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。誠に恐れ入りますが、印刷を頼まれていた資料を、プリンターのインク切れにより印刷できませんでした。何卒ご容赦賜りますよう、お願い申し上げます。', 3, 7),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、厚く御礼申し上げます。誠に恐縮ながら、テスト勉強と重なってしまい、担当部分に手が回っておりません。', 1, 8),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、送信したつもりのメッセージが送れておりませんでした。改めてお送りいたします。', 8, 4),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、内容にこだわりすぎてしまいまして、完成が遅れております。', 4, 7),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。誠に申し訳ございません。課題の範囲を誤解しておりまして、別の部分を作成しておりました。只今作り直しております。', 3, 7),
('友達', '課題の提出遅れ', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐れ入りますが、スマートフォンの充電が切れておりまして、データをお送りできませんでした。今後とも末永くよろしくお願い申し上げます。', 6, 3);

