-- 課題の提出遅れ ／ 家族 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ではございますが、学校に提出する書類へのご署名をお願いするのを失念しておりまして、本日中にご記入を賜りたく存じます。心より深くお詫び申し上げます。', 3, 8),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、進路希望調査票の提出期限が明日でございまして、急ぎご相談させていただきたく存じます。', 3, 9),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。いつも温かく見守っていただき、心より感謝申し上げます。誠に恐れ入りますが、頼まれておりました書類の郵送を失念しておりました。明朝必ず投函いたします。', 2, 6),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ながら、三者面談の日程調査の用紙をお渡しし忘れておりました。何卒ご容赦くださいませ。', 4, 8),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご配慮を賜り、厚く御礼申し上げます。大変恐れ入りますが、課題が終わらず、お手伝いを頼まれていた家計簿の入力が遅れてしまいます。', 1, 9),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。奨学金の書類に不備がございまして、再提出のため改めてご署名を賜りたく存じます。お手数をおかけし、心より深くお詫び申し上げます。', 1, 7),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮でございますが、学校からのお知らせをカバンの奥にしまい込んでおりまして、お渡しが遅れてしまいました。', 2, 10),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、修学旅行の申込書の提出期限が本日でございました。至急ご確認を賜りたく存じます。', 2, 7),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。大変恐縮ではございますが、頼まれておりました年賀状の宛名書きが終わっておりません。今しばらくお待ちくださいませ。', 2, 8),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。誠に恐れ入りますが、学校の健康調査票の記入をお願いし忘れておりました。お手数ではございますが、本日中にご記入くださいますようお願い申し上げます。', 4, 4),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、通知表を学校に置き忘れてしまいまして、お見せするのが遅れてしまいます。', 3, 6),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。平素より大変お世話になっております。誠に恐縮ながら、自由研究の材料の購入をお願いするのを失念しておりました。何卒ご協力賜りますよう、お願い申し上げます。', 1, 11),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。お借りしておりましたパソコンの返却が、課題の作業のため遅れてしまいます。心よりお詫び申し上げます。', 2, 7),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。いつも温かいお心遣いを賜り、厚く御礼申し上げます。大変恐れ入りますが、アルバイトの給与明細をお見せする約束を失念しておりました。', 1, 8),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ではございますが、免許の教習所の申込書の準備が遅れておりまして、ご相談させていただきたく存じます。', 3, 9),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、部活の遠征費の封筒をお渡しし忘れておりました。何卒ご容赦くださいませ。', 5, 7),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。頼まれておりました役所の書類の受け取りを、窓口の受付時間に間に合わず果たせませんでした。明日改めて伺います。', 2, 7),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。誠に恐縮でございますが、成績表の提出期限を勘違いしておりまして、ご署名のお願いが遅れてしまいました。', 6, 6),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。日頃より格別のご高配を賜り、心より御礼申し上げます。誠に申し上げにくいのですが、プリントを雨で濡らしてしまいまして、文字が読めなくなってしまいました。', 2, 10),
('家族', '課題の提出遅れ', '丁寧', '敬愛するご家族の皆様へ。平素より大変お世話になっております。誠に恐縮ながら、学校の集金袋を出し忘れておりまして、期限が明日でございます。今後とも末永くよろしくお願い申し上げます。', 3, 6);

