('家族', '課題の提出遅れ', 'ネタ', 'ちょっと聞いて。プリントの裏に落書きしてたら、名作が生まれた。', 7, 4),
('家族', '課題の提出遅れ', 'ネタ', 'ちょっと聞いて。書類を出すタイミングを、星の動きで見計らってた。', 8, 3),
('家族', '課題の提出遅れ', 'ネタ', 'ちょっと聞いて。カバンの中のプリントが、地層みたいになってた。', 8, 2),
('家族', '課題の提出遅れ', 'ネタ', 'ちょっと聞いて。プリントが洗濯機で洗われて、きれいになって帰ってきた。', 9, 3),
('家族', '課題の提出遅れ', 'ネタ', 'ちょっと聞いて。進路について考えてたら、宇宙について考えてた。', 9, 3),
('家族', '課題の提出遅れ', 'ネタ', 'ちょっと聞いて。提出物の存在を、前向きに忘れてた。', 9, 3);

-- 欠席 ／ 先生 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('先生', '欠席', '丁寧', '先生におかれましては、平素より格別のご指導を賜り、心より御礼申し上げます。誠に申し上げにくいことではございますが、昨夜より発熱しておりまして、本日の授業はお休みさせていただきたく存じます。何卒ご容赦賜りますよう、伏してお願い申し上げます。', 2, 7),
('先生', '欠席', '丁寧', '先生、朝早くから大変失礼いたします。誠に恐縮ではございますが、喉の痛みがひどく声がほとんど出ない状態でございまして、本日は欠席させていただきたく存じます。', 1, 11),
('先生', '欠席', '丁寧', '先生におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、親戚の法事が入っておりまして、本日の授業を欠席させていただきたく存じます。心よりお詫び申し上げます。', 1, 11),
('先生', '欠席', '丁寧', '先生、誠に申し訳ございません。就職活動の面接と授業の日程が重なってしまいまして、本日は欠席させていただきたく存じます。後日、授業の内容を確認させていただきます。', 2, 7),
('先生', '欠席', '丁寧', '先生におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に申し上げにくいのですが、台風により電車が運転を見合わせておりまして、登校することができません。', 3, 9),
('先生', '欠席', '丁寧', '先生、大変恐縮でございます。家族が体調を崩しておりまして、看病のため本日はお休みをいただきたく存じます。何卒ご理解賜りますよう、お願い申し上げます。', 1, 10),
('先生', '欠席', '丁寧', '先生、誠に恐れ入ります。歯の痛みがひどく、急きょ歯科を受診することとなりました。本日の授業を欠席させていただきたく存じます。', 2, 7),
('先生', '欠席', '丁寧', '先生におかれましては、平素より温かいご指導を賜り、心より感謝申し上げます。誠に恐縮ながら、インフルエンザと診断されまして、医師より登校を控えるよう指示を受けております。', 2, 8),
('先生', '欠席', '丁寧', '先生、早朝より失礼いたします。腹痛がひどく、朝から動くことができない状態でございます。本日はお休みさせていただきたく、心よりお詫び申し上げます。', 7, 4),
('先生', '欠席', '丁寧', '先生、誠に申し訳ございません。資格試験の受験日と授業が重なってしまいまして、本日は欠席させていただきたく存じます。何卒ご容赦くださいませ。', 2, 8),
('先生', '欠席', '丁寧', '先生におかれましては、日頃より格別のご高配を賜り、厚く御礼申し上げます。誠に恐れ入りますが、祖父母の通院の付き添いを頼まれておりまして、本日はお休みさせていただきたく存じます。', 1, 9),
('先生', '欠席', '丁寧', '先生、大変失礼いたします。大雪のため自宅周辺の道路が通行できない状態でございまして、登校が困難でございます。何卒ご理解賜りますよう、お願い申し上げます。', 2, 7),
('先生', '欠席', '丁寧', '先生、誠に恐縮でございます。めまいがひどく、本日は安静にするよう医師から言われております。授業を欠席いたしますこと、心よりお詫び申し上げます。', 4, 7),
('先生', '欠席', '丁寧', '先生におかれましては、平素より多大なるご指導を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、企業の説明会に参加するため、本日は欠席させていただきたく存じます。', 2, 7),
('先生', '欠席', '丁寧', '先生、大変申し訳ございません。足首を捻挫してしまいまして、歩くことが困難な状態でございます。本日はお休みをいただきたく存じます。', 3, 5),
('先生', '欠席', '丁寧', '先生、誠に恐れ入りますが、兄の結婚式に出席するため、本日の授業を欠席させていただきたく存じます。何卒ご容赦賜りますよう、お願い申し上げます。', 1, 11),
('先生', '欠席', '丁寧', '先生におかれましては、ますますご健勝のこととお慶び申し上げます。誠に恐縮ながら、健康診断の再検査が本日でございまして、授業を欠席させていただきたく存じます。', 3, 8),
('先生', '欠席', '丁寧', '先生、大変失礼いたします。微熱が続いておりまして、周囲の皆様にうつしてしまうことを避けるため、本日はお休みさせていただきたく存じます。', 2, 7),
('先生', '欠席', '丁寧', '先生、誠に申し訳ございません。部活動の大会に出場するため、本日は公欠とさせていただきたく存じます。お手数をおかけし、心よりお詫び申し上げます。', 2, 10),
('先生', '欠席', '丁寧', '先生におかれましては、平素より格別のご配慮を賜り、心より感謝申し上げます。誠に恐れ入りますが、予防接種の副反応で高熱が出ておりまして、本日はお休みをいただきたく存じます。', 2, 7);

