('先生', '欠席', '普通', '先生、足をひねってしまって歩けないので、今日は休ませてください。', 3, 5),
('先生', '欠席', '普通', '先生、兄の結婚式があるので、今日は欠席します。', 1, 7),
('先生', '欠席', '普通', '先生、健康診断の再検査があって、今日は休ませてください。', 4, 6),
