('先生', '欠席', '普通', '先生、部活の大会があるので、今日は公欠でお願いします。', 3, 9),
('先生', '欠席', '普通', '先生、予防接種の副反応で熱が出たので、休ませてください。', 2, 8);

-- 欠席 ／ 先生 ／ ネタ
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('先生', '欠席', 'ネタ', '先生、聞いてください。布団から出られない呪いにかかりました。今日は解呪に専念します。', 7, 1),
('先生', '欠席', 'ネタ', '先生、朝起きたら猫が私の上で寝ていて、動けません。今日は休みます。', 8, 4),
('先生', '欠席', 'ネタ', '先生、目覚まし時計がストライキを起こしたので、連帯して私も休みます。', 7, 2),
('先生', '欠席', 'ネタ', '先生、今日の運勢が最下位だったので、家で大人しくしています。', 7, 3),
('先生', '欠席', 'ネタ', '先生、こたつに捕まりました。脱出の見込みが立たないため欠席します。', 9, 3),
('先生', '欠席', 'ネタ', '先生、魂がまだ布団に残っているので、体だけ行っても意味がないと思います。', 10, 1),
('先生', '欠席', 'ネタ', '先生、やる気が家出してしまいました。捜索のため今日は休みます。', 6, 3),
('先生', '欠席', 'ネタ', '先生、冬眠の季節が来てしまいました。春に会いましょう。', 6, 2),
('先生', '欠席', 'ネタ', '先生、起きたら夕方でした。今日はもう休んだことにさせてください。', 6, 2),
('先生', '欠席', 'ネタ', '先生、玄関のドアが今日は開かない気分のようです。', 8, 1),
('先生', '欠席', 'ネタ', '先生、自分探しの旅に出ています。見つかったら登校します。', 6, 2),
('先生', '欠席', 'ネタ', '先生、毛布にくるまったら出口がなくなりました。', 7, 2),
('先生', '欠席', 'ネタ', '先生、家の前に知らない猫が座り込んでいて、通してくれません。', 8, 4),
('先生', '欠席', 'ネタ', '先生、宇宙からの電波を受信中で、今は動けません。', 10, 1),
('先生', '欠席', 'ネタ', '先生、昨日の自分に体力を使い切られて、今日の自分の分が残っていません。', 8, 3),
('先生', '欠席', 'ネタ', '先生、カーテンを開けたら外が明るすぎたので、閉めて寝ました。', 11, 1),
('先生', '欠席', 'ネタ', '先生、今日を日曜日だと信じています。どうかそっとしておいてください。', 7, 1),
('先生', '欠席', 'ネタ', '先生、羊を数えていたら逆に目がさえて、朝になってから寝ました。', 8, 1),
('先生', '欠席', 'ネタ', '先生、靴下が全部洗濯中なので、外に出られません。', 7, 1),
('先生', '欠席', 'ネタ', '先生、二度寝が三度寝になり、四度寝の途中で連絡しています。', 7, 3);

-- 欠席 ／ バイト先の店長 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('バイト先の店長', '欠席', '丁寧', '店長におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、昨夜より発熱しておりまして、本日のシフトをお休みさせていただきたく存じます。皆様に多大なるご迷惑をおかけしますこと、心より深くお詫び申し上げます。', 4, 6),
('バイト先の店長', '欠席', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、テスト期間に入りまして、本日のシフトを欠勤させていただきたく存じます。代わりの方を探しておりますので、今しばらくお待ちくださいませ。', 3, 9),
('バイト先の店長', '欠席', '丁寧', '店長におかれましては、平素より格別のご配慮を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、親戚の法事が急きょ入りまして、本日はお休みをいただきたく存じます。', 3, 9),
('バイト先の店長', '欠席', '丁寧', '店長、誠に申し訳ございません。腹痛がひどく、本日の勤務は難しい状態でございます。急なご連絡となり、深くお詫び申し上げます。', 6, 4),
('バイト先の店長', '欠席', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、学校の補講が入ってしまいまして、本日のシフトに入ることができません。何卒ご容赦くださいませ。', 1, 7),
('バイト先の店長', '欠席', '丁寧', '店長におかれましては、日頃より温かいご指導を賜り、心より感謝申し上げます。誠に恐れ入りますが、家族が体調を崩しておりまして、看病のため本日はお休みさせていただきたく存じます。', 1, 7),
('バイト先の店長', '欠席', '丁寧', '店長、誠に恐縮でございます。台風により電車が運休しておりまして、お店まで伺うことができません。何卒ご理解賜りますよう、お願い申し上げます。', 2, 9),
('バイト先の店長', '欠席', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、就職活動の面接が本日入りまして、シフトをお休みさせていただきたく存じます。', 2, 10),
('バイト先の店長', '欠席', '丁寧', '店長におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に恐れ入りますが、インフルエンザと診断されまして、しばらく出勤を控えるよう医師から指示を受けております。', 2, 8),
('バイト先の店長', '欠席', '丁寧', '店長、大変申し訳ございません。喉を痛めてしまいまして、接客が難しい状態でございます。本日のシフトをお休みさせていただきたく存じます。', 3, 9),
('バイト先の店長', '欠席', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、大雪で自宅から出ることができない状態でございます。本日は欠勤させていただきたく存じます。', 3, 9),
('バイト先の店長', '欠席', '丁寧', '店長におかれましては、平素より多大なるご配慮を賜り、厚く御礼申し上げます。誠に恐れ入りますが、研究室の発表準備が終わらず、本日のシフトをお休みさせていただきたく存じます。', 2, 8),
('バイト先の店長', '欠席', '丁寧', '店長、誠に申し訳ございません。足を捻挫してしまいまして、立ち仕事が難しい状態でございます。何卒ご容赦賜りますよう、お願い申し上げます。', 3, 8),
('バイト先の店長', '欠席', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、兄弟の卒業式に出席するため、本日はお休みをいただきたく存じます。事前のご相談が遅れましたこと、深くお詫び申し上げます。', 2, 7),
('バイト先の店長', '欠席', '丁寧', '店長におかれましては、日頃より格別のご高配を賜り、心より感謝申し上げます。誠に恐縮ではございますが、めまいがひどく、本日の勤務は難しい状態でございます。', 4, 6),
('バイト先の店長', '欠席', '丁寧', '店長、誠に恐縮でございます。資格試験の受験日と重なってしまいまして、本日のシフトをお休みさせていただきたく存じます。', 1, 8),
('バイト先の店長', '欠席', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、自宅の水道設備が故障いたしまして、業者の立ち会いのため本日はお休みをいただきたく存じます。', 1, 7),
('バイト先の店長', '欠席', '丁寧', '店長におかれましては、平素より大変お世話になっております。誠に恐れ入りますが、予防接種の副反応で高熱が出ておりまして、本日は欠勤させていただきたく存じます。', 2, 6),
('バイト先の店長', '欠席', '丁寧', '店長、大変申し訳ございません。祖父母の通院の付き添いを頼まれてしまいまして、本日はお休みをいただきたく存じます。重ねてお詫び申し上げます。', 2, 6),
('バイト先の店長', '欠席', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、学校の行事が延長となりまして、本日のシフトに間に合わない見込みでございます。何卒よろしくお願い申し上げます。', 3, 9);

