-- 欠席 ／ 友達 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('友達', '欠席', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、昨夜より発熱しておりまして、本日のお約束をお休みさせていただきたく存じます。心より深くお詫び申し上げます。', 2, 7),
('友達', '欠席', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に申し上げにくいのですが、家族の用事が急きょ入りまして、本日の遊びのお約束に参加することができなくなりました。', 1, 11),
('友達', '欠席', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、心より感謝申し上げます。誠に恐れ入りますが、アルバイトのシフトが急に入ってしまいまして、本日はお休みさせていただきたく存じます。', 1, 7),
('友達', '欠席', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ながら、課題の締め切りが迫っておりまして、本日のお約束を辞退させていただきたく存じます。', 4, 8),
('友達', '欠席', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、腹痛がひどく、本日の外出は難しい状態でございます。何卒ご容赦くださいませ。', 5, 3),
('友達', '欠席', '丁寧', '親愛なる友へ。誠に申し訳ございません。台風により電車が運休しておりまして、お約束の場所へ伺うことができません。今後とも変わらぬご厚誼を賜りますよう、お願い申し上げます。', 1, 8),
('友達', '欠席', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、テスト勉強が終わっておりませんで、本日のお誘いをお断りさせていただきたく存じます。', 1, 10),
('友達', '欠席', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐縮ではございますが、喉を痛めてしまいまして、本日のカラオケへの参加を見送らせていただきたく存じます。', 1, 8),
('友達', '欠席', '丁寧', '親愛なる友へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、親戚が遠方より参りますため、本日は自宅におらねばなりません。', 2, 10),
('友達', '欠席', '丁寧', '親愛なる友へ。誠に恐縮ではございますが、大雪のため自宅から出ることができない状態でございます。本日のお約束は、また改めさせていただけますと幸いでございます。', 2, 7),
('友達', '欠席', '丁寧', '親愛なる友へ。平素より大変お世話になっております。誠に恐れ入りますが、就職活動の準備が立て込んでおりまして、本日の集まりを欠席させていただきたく存じます。', 3, 5),
('友達', '欠席', '丁寧', '親愛なる友へ。いつも格別のお心遣いを賜り、厚く御礼申し上げます。大変恐縮ながら、めまいがいたしまして、本日は自宅にて安静にしております。', 2, 6),
('友達', '欠席', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に恐縮でございますが、弟の面倒を見ることになりまして、本日の外出が難しくなってしまいました。', 4, 5),
('友達', '欠席', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、心より御礼申し上げます。誠に申し上げにくいのですが、自宅の水道設備の修理に立ち会うことになりまして、本日はお休みをいただきます。', 1, 10),
('友達', '欠席', '丁寧', '親愛なる友へ。誠に恐れ入りますが、研究室の作業が終わらず、本日のお約束に伺うことができません。何卒ご容赦賜りますよう、お願い申し上げます。', 3, 5),
('友達', '欠席', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、厚く御礼申し上げます。誠に恐縮ながら、歯の痛みがひどく、急きょ歯科を受診することとなりました。', 2, 9),
('友達', '欠席', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、足を捻挫してしまいまして、本日の外出は難しい状態でございます。', 3, 8),
('友達', '欠席', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、家族旅行の予定が前より入っておりまして、本日はご一緒できません。', 2, 8),
('友達', '欠席', '丁寧', '親愛なる友へ。誠に申し訳ございません。寝不足がたたりまして体調を崩してしまいました。本日はお休みさせていただきたく、心よりお詫び申し上げます。', 1, 8),
('友達', '欠席', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐れ入りますが、免許の教習の予約が本日入っておりまして、ご一緒することができません。今後とも末永くよろしくお願い申し上げます。', 3, 5);

