-- 欠席 ／ 家族 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ではございますが、課題の締め切りが迫っておりまして、本日の家族での外食を欠席させていただきたく存じます。心より深くお詫び申し上げます。', 1, 8),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、アルバイトのシフトが入っておりまして、本日の親戚の集まりに参加することができません。', 1, 8),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。いつも温かく見守っていただき、心より感謝申し上げます。誠に恐れ入りますが、テスト期間中でございまして、週末の家族旅行への同行を辞退させていただきたく存じます。', 2, 8),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ながら、発熱しておりまして、本日の祖父母宅への訪問を見送らせていただきたく存じます。', 2, 7),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご配慮を賜り、厚く御礼申し上げます。大変恐れ入りますが、部活動の練習試合が入っておりまして、本日の買い物にはご一緒できません。', 2, 9),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。就職活動の面接が入りまして、本日の家族の行事を欠席させていただきたく存じます。何卒ご容赦くださいませ。', 3, 9),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮でございますが、研究室の発表準備が終わらず、本日の大掃除のお手伝いができそうにございません。', 1, 9),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、友人と前より約束がございまして、本日の夕食は外で済ませる予定でございます。', 2, 6),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。大変恐縮ではございますが、腹痛がひどく、本日の外出は控えさせていただきたく存じます。', 4, 4),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。誠に恐れ入りますが、資格試験の勉強に集中したく、本日の親戚の集まりを欠席させていただけますと幸いでございます。', 1, 10),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、学校の行事の準備がございまして、本日は帰宅が遅くなり夕食をご一緒できません。', 2, 7),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。平素より大変お世話になっております。誠に恐縮ながら、喉を痛めておりまして、本日の家族カラオケへの参加を見送らせていただきたく存じます。', 3, 9),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。アルバイトの研修と重なってしまいまして、本日の墓参りに同行することができません。心よりお詫び申し上げます。', 1, 9),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。いつも温かいお心遣いを賜り、厚く御礼申し上げます。大変恐れ入りますが、委員会の仕事が入ってしまいまして、本日の家族の買い出しに参加できません。', 2, 8),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ではございますが、寝不足で体調が優れず、本日の外出は控えさせていただきたく存じます。', 3, 9),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、教習所の予約が入っておりまして、本日の祖母宅への訪問に同行できません。', 1, 9),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。課題のグループ作業が入りまして、本日の家族での食事会を欠席させていただきたく存じます。', 2, 7),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。誠に恐縮でございますが、ボランティアの予定が前より入っておりまして、本日はご一緒できません。', 2, 6),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。日頃より格別のご高配を賜り、心より御礼申し上げます。誠に申し上げにくいのですが、めまいがいたしまして、本日は自室にて安静にしております。', 2, 9),
('家族', '欠席', '丁寧', '敬愛するご家族の皆様へ。平素より大変お世話になっております。誠に恐縮ながら、企業の説明会に参加するため、本日の家族の予定を欠席させていただきたく存じます。今後とも末永くよろしくお願い申し上げます。', 2, 6);

