-- 欠席 ／ 家族 ／ ネタ
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('家族', '欠席', 'ネタ', 'ちょっと聞いて。布団から出られない呪いにかかった。今日は家族会議も欠席します。', 6, 2),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。部屋の居心地が良すぎて、外の世界に出る理由が見つからない。', 11, 1),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。猫が私の上で寝てるから、今日の予定は全部キャンセルで。', 7, 2),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。こたつに捕まった。救出は明日以降でお願い。', 6, 2),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。やる気が家出した。たぶん夕飯までには帰ってくる。', 11, 1),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。冬眠に入ります。起こさないでください。', 9, 1),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。今日の運勢で「外出は大凶」と出たから、家族のためにも家にいる。', 10, 1),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。自分探しの旅で忙しいので、親戚の集まりはパスで。', 10, 1),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。魂がまだ布団の中で、体だけ行っても意味がないと思う。', 8, 4),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。毛布にくるまったら出口がなくなった。', 8, 1),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。起きたら夕方で、もう今日が終わってた。', 8, 1),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。宇宙からの電波を受信中だから、部屋から出られない。', 11, 1),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。窓から見える雲を数えるので忙しい。', 8, 3),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。今日を日曜日だと信じてる。そっとしておいて。', 6, 2),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。靴下が全部洗濯中だから外に出られない。', 5, 3),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。昨日の自分に体力を全部使われた。', 8, 0),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。枕との相性が良すぎて、離れるのがつらい。', 10, 1),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。雨の音が心地よすぎて、今日は雨を聴く日にした。', 8, 2),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。読み始めた漫画が止まらなくて、全巻読むまで出られない。', 9, 2),
('家族', '欠席', 'ネタ', 'ちょっと聞いて。家の植物に話しかけられた気がして、相談に乗ってる。', 11, 1);

-- 飲み会を断る ／ 先生 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('先生', '飲み会を断る', '丁寧', '先生におかれましては、平素より格別のご指導を賜り、心より御礼申し上げます。せっかく懇親会にお誘いいただきながら誠に恐縮ではございますが、その日は前より家族との予定が入っておりまして、誠に勝手ながら今回は参加を見送らせていただきたく存じます。何卒ご容赦賜りますよう、伏してお願い申し上げます。', 2, 8),
('先生', '飲み会を断る', '丁寧', '先生、この度は打ち上げにお声がけいただき、誠にありがとうございます。大変申し上げにくいのですが、翌日の朝早くから資格試験がございまして、今回は辞退させていただきたく存じます。', 1, 8),
('先生', '飲み会を断る', '丁寧', '先生におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、アルバイトのシフトが入っておりまして、研究室の懇親会への参加が難しい状況でございます。心よりお詫び申し上げます。', 2, 7),
('先生', '飲み会を断る', '丁寧', '先生、ゼミの打ち上げにお誘いいただき、心より感謝申し上げます。誠に恐縮ながら、体調が優れない日が続いておりまして、今回は大事を取らせていただきたく存じます。', 3, 8),
('先生', '飲み会を断る', '丁寧', '先生におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に申し上げにくいのですが、自宅が遠方にございまして、帰りの交通手段が確保できないため、今回は参加を見送らせていただきます。', 4, 7),
('先生', '飲み会を断る', '丁寧', '先生、懇親会のご案内、誠にありがとうございます。大変恐れ入りますが、就職活動の面接が翌日に控えておりまして、準備に専念させていただきたく存じます。', 3, 9),
('先生', '飲み会を断る', '丁寧', '先生、誠に恐縮でございます。お酒をいただくことができない体質でございまして、皆様にお気を遣わせてしまうことを避けたく、今回は辞退させていただきたく存じます。', 3, 8),
('先生', '飲み会を断る', '丁寧', '先生におかれましては、平素より温かいご指導を賜り、心より感謝申し上げます。誠に恐れ入りますが、発表資料の作成が終わっておりませんで、今回は失礼させていただきたく存じます。', 5, 7),
('先生', '飲み会を断る', '丁寧', '先生、打ち上げへのお誘い、身に余る光栄でございます。誠に申し上げにくいのですが、門限がございまして、最後までご一緒することがかないません。今回は辞退させていただきます。', 2, 7),
('先生', '飲み会を断る', '丁寧', '先生、誠に恐れ入ります。その日は親戚の集まりが前より予定されておりまして、懇親会への参加が難しい状況でございます。またの機会にぜひご一緒させていただけますと幸いでございます。', 3, 8),
('先生', '飲み会を断る', '丁寧', '先生におかれましては、日頃より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ながら、通院中で服薬しておりまして、お酒を控えるよう言われております。', 2, 6),
('先生', '飲み会を断る', '丁寧', '先生、お誘いいただき誠にありがとうございます。大変恐れ入りますが、部活動の大会が翌日に控えておりまして、体調を整えたく存じます。何卒ご容赦くださいませ。', 3, 9),
('先生', '飲み会を断る', '丁寧', '先生、誠に申し訳ございません。課題の締め切りが重なっておりまして、今回の懇親会は欠席させていただきたく存じます。後日、皆様のお話を伺えますと幸いでございます。', 3, 6),
('先生', '飲み会を断る', '丁寧', '先生におかれましては、平素より多大なるご指導を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、その日は弟の面倒を見る当番でございまして、参加がかないません。', 3, 5),
('先生', '飲み会を断る', '丁寧', '先生、懇親会のご案内を頂戴し、心より感謝申し上げます。誠に恐縮ではございますが、早朝からのアルバイトが翌日にございまして、今回は辞退させていただきたく存じます。', 4, 7),
('先生', '飲み会を断る', '丁寧', '先生、誠に恐れ入りますが、最近寝不足が続いておりまして、体調管理のため夜の予定を控えております。何卒ご理解賜りますよう、お願い申し上げます。', 2, 9),
('先生', '飲み会を断る', '丁寧', '先生におかれましては、ますますご健勝のこととお慶び申し上げます。誠に恐縮ながら、その時間帯はオンラインの講座を受講しておりまして、参加することができません。', 4, 8),
('先生', '飲み会を断る', '丁寧', '先生、お声がけいただき誠に光栄でございます。大変恐れ入りますが、家族の誕生日でございまして、自宅でお祝いをする約束をしております。今回は失礼いたします。', 2, 8),
('先生', '飲み会を断る', '丁寧', '先生、誠に申し訳ございません。今月は出費がかさんでおりまして、誠に勝手ながら今回は参加を見送らせていただきたく存じます。', 6, 4),
('先生', '飲み会を断る', '丁寧', '先生におかれましては、平素より格別のご配慮を賜り、心より感謝申し上げます。誠に恐れ入りますが、留守番を頼まれておりまして、その日は自宅を空けることができません。', 2, 7);

