('先生', '飲み会を断る', '普通', '先生、発表資料がまだ終わっていないので、今回は失礼します。', 4, 4),
('先生', '飲み会を断る', '普通', '先生、門限があって最後までいられないので、今回はやめておきます。', 2, 8),
('先生', '飲み会を断る', '普通', '先生、その日は親戚の集まりがあって行けません。また誘ってください。', 1, 8),
('先生', '飲み会を断る', '普通', '先生、薬を飲んでいてお酒を控えているので、今回は遠慮します。', 2, 8),
('先生', '飲み会を断る', '普通', '先生、次の日に部活の大会があるので、今回は休ませてください。', 2, 6),
('先生', '飲み会を断る', '普通', '先生、課題の締め切りが重なっているので、今回は欠席します。', 4, 6),
('先生', '飲み会を断る', '普通', '先生、その日は弟の面倒を見る日なので行けません。すみません。', 4, 7),
