('先生', '飲み会を断る', '普通', '先生、最近寝不足なので、夜の予定は控えています。すみません。', 4, 6),
('先生', '飲み会を断る', '普通', '先生、その時間はオンライン講座があるので参加できません。', 3, 5),
('先生', '飲み会を断る', '普通', '先生、家族の誕生日なので、家でお祝いする予定です。すみません。', 1, 9),
('先生', '飲み会を断る', '普通', '先生、今月は出費が多くて、今回は見送らせてください。', 5, 4),
('先生', '飲み会を断る', '普通', '先生、留守番を頼まれていて家を空けられません。すみません。', 4, 6);

-- 飲み会を断る ／ 先生 ／ ネタ
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('先生', '飲み会を断る', 'ネタ', '先生、聞いてください。その日は家で自分と乾杯する先約がありまして。', 9, 2),
('先生', '飲み会を断る', 'ネタ', '先生、懇親会の日は満月なので、家で月を見る予定です。', 6, 3),
('先生', '飲み会を断る', 'ネタ', '先生、財布が冬眠中で、春まで起きない見込みです。', 6, 2),
('先生', '飲み会を断る', 'ネタ', '先生、お酒を見るだけで眠くなる体質なので、会場で寝る自信があります。', 8, 3),
('先生', '飲み会を断る', 'ネタ', '先生、その日は推しの誕生日なので、全力でお祝いしなければなりません。', 10, 2),
('先生', '飲み会を断る', 'ネタ', '先生、家の布団に「今夜は早く帰ってこい」と言われています。', 10, 2),
('先生', '飲み会を断る', 'ネタ', '先生、飲み会の神様に「今回は休め」とお告げを受けました。', 9, 2),
('先生', '飲み会を断る', 'ネタ', '先生、夜九時を過ぎると溶けてしまう体質なんです。', 7, 2),
('先生', '飲み会を断る', 'ネタ', '先生、カレーを三日分作ってしまい、消費しなければなりません。', 6, 3),
('先生', '飲み会を断る', 'ネタ', '先生、今夜は流星群が見られるらしいので、願い事を準備しています。', 9, 2),
('先生', '飲み会を断る', 'ネタ', '先生、前回の打ち上げの記憶が、まだ戻ってきていません。', 7, 2),
('先生', '飲み会を断る', 'ネタ', '先生、金魚のエサやり当番なので、家を空けられません。', 7, 1),
('先生', '飲み会を断る', 'ネタ', '先生、その日はひとり焼肉の予約を入れてしまいました。', 9, 3),
('先生', '飲み会を断る', 'ネタ', '先生、家のこたつと先約があります。', 9, 1),
('先生', '飲み会を断る', 'ネタ', '先生、飲み会で話せる鉄板ネタが尽きてしまいました。補充期間をください。', 7, 1),
('先生', '飲み会を断る', 'ネタ', '先生、猫の爪切りをする約束をしています。猫との約束は破れません。', 7, 1),
('先生', '飲み会を断る', 'ネタ', '先生、今月の運勢で「夜の外出は控えめに」と出ていました。', 5, 3),
('先生', '飲み会を断る', 'ネタ', '先生、アイスを冷凍庫に入れ忘れた気がして、確かめに帰らないといけません。', 8, 1),
('先生', '飲み会を断る', 'ネタ', '先生、新しいパジャマを早く着たい気持ちが抑えられません。', 11, 1),
('先生', '飲み会を断る', 'ネタ', '先生、明日の自分に優しくしたいので、今日の自分は早く寝ます。', 10, 1);

-- 飲み会を断る ／ バイト先の店長 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('バイト先の店長', '飲み会を断る', '丁寧', '店長におかれましては、日頃より大変お世話になっております。せっかく歓迎会にお誘いいただきながら誠に恐縮ではございますが、その日は前より家族との予定が入っておりまして、誠に勝手ながら今回は参加を見送らせていただきたく存じます。', 2, 7),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、お疲れさまでございます。忘年会へのお声がけ、誠にありがとうございます。大変申し上げにくいのですが、翌日にテストがございまして、今回は辞退させていただきたく存じます。', 2, 10),
('バイト先の店長', '飲み会を断る', '丁寧', '店長におかれましては、平素より格別のご配慮を賜り、厚く御礼申し上げます。誠に恐れ入りますが、課題の締め切りが迫っておりまして、送別会への参加が難しい状況でございます。', 3, 8),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、お酒をいただくことができない体質でございまして、今回は辞退させていただきたく存じます。皆様によろしくお伝えくださいませ。', 3, 6),
('バイト先の店長', '飲み会を断る', '丁寧', '店長におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に申し上げにくいのですが、門限がございまして、今回の飲み会は失礼させていただきたく存じます。', 2, 9),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、飲み会のご案内、誠にありがとうございます。大変恐れ入りますが、就職活動の面接が翌日に控えておりまして、準備に専念させていただきたく存じます。', 2, 8),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、お疲れさまでございます。誠に恐縮でございますが、自宅が遠方にございまして、終電の時刻が早いため、今回は参加を見送らせていただきます。', 2, 7),
('バイト先の店長', '飲み会を断る', '丁寧', '店長におかれましては、平素より温かいご指導を賜り、心より感謝申し上げます。誠に恐れ入りますが、体調が優れない日が続いておりまして、今回は大事を取らせていただきたく存じます。', 1, 10),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、親戚の集まりが前より予定されておりまして、参加が難しい状況でございます。またの機会にぜひご一緒させてくださいませ。', 2, 6),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、誠に恐れ入ります。翌日が早朝からのシフトでございまして、体調を整えたく存じます。何卒ご容赦くださいませ。', 1, 7),
('バイト先の店長', '飲み会を断る', '丁寧', '店長におかれましては、日頃より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ながら、通院中で服薬しておりまして、お酒を控えるよう言われております。', 2, 9),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、資格試験が近づいておりまして、勉強に専念させていただきたく存じます。', 2, 8),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、お誘いいただき心より感謝申し上げます。誠に申し訳ございませんが、その日は弟の面倒を見る当番でございまして、参加がかないません。', 3, 6),
('バイト先の店長', '飲み会を断る', '丁寧', '店長におかれましては、平素より多大なるご配慮を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、今月は出費がかさんでおりまして、今回は失礼させていただきます。', 6, 3),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、お疲れさまでございます。誠に恐縮ではございますが、部活動の大会が翌日に控えておりまして、今回は辞退させていただきたく存じます。', 2, 7),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、誠に恐れ入りますが、研究室の発表準備が終わっておりませんで、今回の飲み会は欠席させていただきたく存じます。', 3, 6),
('バイト先の店長', '飲み会を断る', '丁寧', '店長におかれましては、ますますご健勝のこととお慶び申し上げます。誠に恐縮ながら、家族の誕生日でございまして、自宅でお祝いをする約束をしております。', 1, 7),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、留守番を頼まれておりまして、その日は自宅を空けることができません。', 3, 6),
('バイト先の店長', '飲み会を断る', '丁寧', '店長、お声がけいただき誠に光栄でございます。誠に申し上げにくいのですが、最近寝不足が続いておりまして、夜の予定を控えております。', 4, 7),
('バイト先の店長', '飲み会を断る', '丁寧', '店長におかれましては、平素より格別のご配慮を賜り、心より感謝申し上げます。誠に恐れ入りますが、その時間帯は教習所の予約が入っておりまして、参加することができません。', 3, 7);

