('バイト先の店長', '飲み会を断る', 'ネタ', '店長、夜九時を過ぎると溶ける体質なので、店に迷惑がかかります。', 8, 2),
('バイト先の店長', '飲み会を断る', 'ネタ', '店長、その日は推しの配信があります。人生がかかっています。', 8, 1),
