-- 飲み会を断る ／ 友達 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。せっかく飲み会にお誘いいただきながら誠に恐縮ではございますが、その日は前より家族との予定が入っておりまして、誠に勝手ながら今回は参加を見送らせていただきたく存じます。', 1, 9),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に申し上げにくいのですが、翌日にテストがございまして、今回は辞退させていただきたく存じます。今後とも変わらぬご厚誼を賜りますよう、お願い申し上げます。', 1, 10),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、心より感謝申し上げます。誠に恐れ入りますが、アルバイトのシフトが入っておりまして、今回はご一緒することがかないません。', 2, 8),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ながら、今月は出費がかさんでおりまして、今回は失礼させていただきたく存じます。', 7, 5),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、課題の締め切りが迫っておりまして、今回の飲み会は欠席させていただきたく存じます。', 3, 6),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。誠に申し訳ございません。お酒をいただくことができない体質でございまして、皆様の楽しいお時間を損ねてしまうことを避けたく存じます。', 4, 6),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、門限がございまして、最後までご一緒することがかないません。', 1, 8),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐縮ではございますが、最近疲れがたまっておりまして、今回は大事を取らせていただきたく存じます。', 3, 6),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、翌朝が大変早く、体調を整えたく存じます。', 3, 9),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。誠に恐縮ではございますが、通院中で服薬しておりまして、お酒を控えるよう言われております。またの機会にぜひご一緒させてくださいませ。', 1, 9),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。平素より大変お世話になっております。誠に恐れ入りますが、地元の友人と前より約束がございまして、今回はご一緒できません。', 1, 9),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。いつも格別のお心遣いを賜り、厚く御礼申し上げます。大変恐縮ながら、就職活動の準備が立て込んでおりまして、今回は辞退させていただきます。', 3, 7),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に恐縮でございますが、家族の誕生日でございまして、自宅でお祝いをする約束をしております。', 3, 9),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、心より御礼申し上げます。誠に申し上げにくいのですが、自宅が遠方にございまして、終電の時刻が早いため参加が難しい状況でございます。', 2, 6),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。誠に恐れ入りますが、資格試験が近づいておりまして、勉強に専念させていただきたく存じます。何卒ご容赦賜りますよう、お願い申し上げます。', 2, 7),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、厚く御礼申し上げます。誠に恐縮ながら、部活動の練習が入っておりまして、今回は参加を見送らせていただきます。', 3, 8),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、大人数の集まりが少々苦手でございまして、今回はご遠慮させていただきたく存じます。', 3, 7),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、引っ越しの準備がございまして、今回はご一緒できません。', 4, 6),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。誠に申し訳ございません。最近飲み会が続いておりまして、体を休めたく存じます。心よりお詫び申し上げます。', 2, 6),
('友達', '飲み会を断る', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐れ入りますが、留守番を頼まれておりまして、その日は自宅を空けることができません。今後とも末永くよろしくお願い申し上げます。', 3, 6);

