-- 飲み会を断る ／ 家族 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。せっかく親戚の宴会にお誘いいただきながら誠に恐縮ではございますが、課題の締め切りが迫っておりまして、誠に勝手ながら今回は参加を見送らせていただきたく存じます。', 1, 10),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、アルバイトのシフトが入っておりまして、本日の家族での会食には参加できません。', 1, 7),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。いつも温かく見守っていただき、心より感謝申し上げます。誠に恐れ入りますが、翌日にテストがございまして、本日の晩酌のお付き合いはご遠慮させていただきたく存じます。', 1, 8),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ながら、友人と前より約束がございまして、本日の親戚の集まりを欠席させていただきたく存じます。', 2, 9),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご配慮を賜り、厚く御礼申し上げます。大変恐れ入りますが、お酒が得意ではございませんで、乾杯のみで失礼させていただきたく存じます。', 3, 7),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。就職活動の面接が翌日に控えておりまして、本日の宴会は早めに失礼させていただきたく存じます。', 2, 7),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮でございますが、研究室の作業が終わっておりませんで、本日の忘年会を欠席させていただきたく存じます。', 1, 10),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、体調が優れない日が続いておりまして、本日は自室で休ませていただきたく存じます。', 1, 7),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。大変恐縮ではございますが、資格試験の勉強に集中したく、本日の新年会は欠席させていただけますと幸いでございます。', 2, 10),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。誠に恐れ入りますが、部活動の大会が翌日に控えておりまして、本日は早めに休ませていただきたく存じます。', 2, 6),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、委員会の仕事がございまして、本日のお祝いの席に間に合いそうにございません。', 2, 9),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。平素より大変お世話になっております。誠に恐縮ながら、レポートの提出が明日でございまして、本日の食事会を辞退させていただきたく存じます。', 2, 8),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。翌朝が早朝からのアルバイトでございまして、本日の宴会は乾杯のみで失礼させていただきます。', 1, 7),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。いつも温かいお心遣いを賜り、厚く御礼申し上げます。大変恐れ入りますが、オンラインの講座がその時間帯にございまして、本日は参加できません。', 1, 7),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ではございますが、喉の調子が優れず、本日の宴会での歌唱はご遠慮させていただきたく存じます。', 2, 6),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、ゼミの準備が終わっておりませんで、本日の会食を欠席させていただきたく存じます。', 2, 6),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。最近寝不足が続いておりまして、本日は早めに休ませていただきたく存じます。', 1, 8),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。誠に恐縮でございますが、教習所の予約が入っておりまして、本日の親戚の集まりに伺うことができません。', 2, 7),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。日頃より格別のご高配を賜り、心より御礼申し上げます。誠に申し上げにくいのですが、ダイエット中でございまして、本日のごちそうは控えさせていただきたく存じます。', 1, 10),
('家族', '飲み会を断る', '丁寧', '敬愛するご家族の皆様へ。平素より大変お世話になっております。誠に恐縮ながら、ボランティアの予定が前より入っておりまして、本日の宴会を欠席させていただきたく存じます。今後とも末永くよろしくお願い申し上げます。', 2, 7);

