-- 既読スルー ／ 先生 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('先生', '既読スルー', '丁寧', '先生におかれましては、平素より格別のご指導を賜り、心より御礼申し上げます。誠に申し上げにくいことではございますが、ご連絡を拝読しながら、内容を確認したうえでお返事しようと考えておりましたところ、ご返信が大変遅くなってしまいました。何卒ご容赦賜りますよう、伏してお願い申し上げます。', 4, 7),
('先生', '既読スルー', '丁寧', '先生、ご連絡いただきながら、ご返信が遅くなり誠に申し訳ございません。授業中に拝読いたしまして、その後お返事を失念しておりました。心より深くお詫び申し上げます。', 1, 11),
('先生', '既読スルー', '丁寧', '先生におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、ご返信の文面を考えておりましたところ時間が経ってしまい、大変失礼いたしました。', 2, 7),
('先生', '既読スルー', '丁寧', '先生、誠に申し訳ございません。ご連絡を拝読した直後に携帯電話の充電が切れてしまいまして、ご返信が遅れてしまいました。重ねてお詫び申し上げます。', 8, 4),
('先生', '既読スルー', '丁寧', '先生におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に恐縮ではございますが、家族に予定を確認してからお返事しようと考えており、ご返信が遅くなりました。', 3, 7),
('先生', '既読スルー', '丁寧', '先生、大変恐縮でございます。返信を作成したつもりで、送信できていなかったことに先ほど気づきました。誠に失礼いたしました。', 5, 4),
('先生', '既読スルー', '丁寧', '先生、誠に恐れ入ります。体調を崩して寝込んでおりまして、ご連絡を拝読したまま、お返事ができずにおりました。何卒ご容赦くださいませ。', 2, 6),
('先生', '既読スルー', '丁寧', '先生におかれましては、平素より温かいご指導を賜り、心より感謝申し上げます。誠に恐縮ながら、大切なご連絡でございましたので、落ち着いてからお返事しようと考えておりました。', 3, 5),
('先生', '既読スルー', '丁寧', '先生、早朝より失礼いたします。アルバイト中にご連絡を拝読いたしまして、終了後にお返事しようと思いながら失念してしまいました。心よりお詫び申し上げます。', 2, 9),
('先生', '既読スルー', '丁寧', '先生、誠に申し訳ございません。アプリの不具合で送信エラーとなっていたことに気づかず、ご返信が遅れてしまいました。', 7, 4),
('先生', '既読スルー', '丁寧', '先生におかれましては、日頃より格別のご高配を賜り、厚く御礼申し上げます。誠に恐れ入りますが、シフトを確認してからご返信しようと考えておりまして、大変遅くなってしまいました。', 2, 10),
('先生', '既読スルー', '丁寧', '先生、大変失礼いたしました。ご連絡を拝読したあと、課題に追われておりまして、ご返信が遅れてしまいました。深く反省しております。', 3, 8),
('先生', '既読スルー', '丁寧', '先生、誠に恐縮でございます。寝ぼけた状態でご連絡を開いてしまいまして、拝読した記憶が曖昧になっておりました。大変失礼いたしました。', 6, 3),
('先生', '既読スルー', '丁寧', '先生におかれましては、平素より多大なるご指導を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、通知から開いたまま閉じてしまい、ご返信を失念しておりました。', 5, 4),
('先生', '既読スルー', '丁寧', '先生、大変申し訳ございません。ご連絡を拝読した直後にお電話がかかってまいりまして、そのままお返事を忘れてしまいました。', 5, 3),
('先生', '既読スルー', '丁寧', '先生、誠に恐れ入りますが、移動中にご連絡を拝読いたしまして、電波の悪い場所でお返事を送ることができませんでした。', 5, 6),
('先生', '既読スルー', '丁寧', '先生におかれましては、ますますご健勝のこととお慶び申し上げます。誠に恐縮ながら、ご質問への正確な回答を調べておりまして、ご返信が遅くなってしまいました。', 4, 8),
('先生', '既読スルー', '丁寧', '先生、大変失礼いたします。返信を下書きしたまま、送信するのを忘れておりました。誠に申し訳ございません。', 5, 3),
('先生', '既読スルー', '丁寧', '先生、誠に申し訳ございません。面接の直前にご連絡を拝読いたしまして、その後お返事が遅くなってしまいました。何卒ご容赦くださいませ。', 1, 10),
('先生', '既読スルー', '丁寧', '先生におかれましては、平素より格別のご配慮を賜り、心より感謝申し上げます。誠に恐れ入りますが、ほかのご連絡に紛れてしまいまして、ご返信が遅れてしまいました。', 7, 4);

