-- 既読スルー ／ バイト先の店長 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('バイト先の店長', '既読スルー', '丁寧', '店長におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、シフトのご連絡を拝読しながら、予定を確認してからお返事しようと考えておりましたところ、ご返信が大変遅くなってしまいました。心より深くお詫び申し上げます。', 2, 10),
('バイト先の店長', '既読スルー', '丁寧', '店長、お疲れさまでございます。ご連絡を拝読しながらご返信が遅れ、誠に申し訳ございません。授業中でございまして、その後失念しておりました。', 3, 9),
('バイト先の店長', '既読スルー', '丁寧', '店長におかれましては、平素より格別のご配慮を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、学校の予定を確認しておりまして、ご返信が遅くなってしまいました。', 3, 5),
('バイト先の店長', '既読スルー', '丁寧', '店長、誠に申し訳ございません。ご連絡を拝読した直後に携帯電話の充電が切れてしまいまして、ご返信が遅れてしまいました。', 4, 4),
('バイト先の店長', '既読スルー', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、送信したつもりの返信が送れておりませんでした。先ほど気づき、大変失礼いたしました。', 7, 5),
('バイト先の店長', '既読スルー', '丁寧', '店長におかれましては、日頃より温かいご指導を賜り、心より感謝申し上げます。誠に恐れ入りますが、家族に予定を確認してからお返事しようと考えておりました。', 3, 5),
('バイト先の店長', '既読スルー', '丁寧', '店長、誠に恐縮でございます。体調を崩して寝込んでおりまして、ご連絡を拝読したまま、お返事ができずにおりました。', 3, 8),
('バイト先の店長', '既読スルー', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、テスト勉強に集中しておりまして、ご返信が遅れてしまいました。', 2, 9),
('バイト先の店長', '既読スルー', '丁寧', '店長におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に恐れ入りますが、ご返信の文面を考えておりましたところ、時間が経ってしまいました。', 3, 8),
('バイト先の店長', '既読スルー', '丁寧', '店長、大変申し訳ございません。通知から開いたまま閉じてしまい、ご返信を失念しておりました。', 6, 5),
('バイト先の店長', '既読スルー', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、アプリの不具合で送信エラーとなっていたことに気づきませんでした。', 6, 4),
('バイト先の店長', '既読スルー', '丁寧', '店長におかれましては、平素より多大なるご配慮を賜り、厚く御礼申し上げます。誠に恐れ入りますが、移動中で電波が悪く、お返事を送ることができませんでした。', 4, 7),
('バイト先の店長', '既読スルー', '丁寧', '店長、誠に申し訳ございません。ご連絡を拝読した直後に家族に呼ばれまして、そのままお返事を忘れてしまいました。', 6, 5),
('バイト先の店長', '既読スルー', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、代わりに入れる方を探してからお返事しようと考えておりまして、遅くなってしまいました。', 3, 6),
('バイト先の店長', '既読スルー', '丁寧', '店長におかれましては、日頃より格別のご高配を賜り、心より感謝申し上げます。誠に恐縮ではございますが、ほかのご連絡に紛れてしまいまして、ご返信が遅れてしまいました。', 6, 4),
('バイト先の店長', '既読スルー', '丁寧', '店長、誠に恐縮でございます。返信を下書きしたまま、送信するのを忘れておりました。大変失礼いたしました。', 5, 3),
('バイト先の店長', '既読スルー', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、寝ぼけた状態でご連絡を開いてしまい、拝読した記憶が曖昧になっておりました。', 7, 5),
('バイト先の店長', '既読スルー', '丁寧', '店長におかれましては、平素より大変お世話になっております。誠に恐れ入りますが、研究室の作業に集中しておりまして、ご返信が遅くなってしまいました。', 4, 7),
('バイト先の店長', '既読スルー', '丁寧', '店長、大変申し訳ございません。ご連絡を拝読した直後にお電話がかかってまいりまして、お返事を失念してしまいました。', 4, 6),
('バイト先の店長', '既読スルー', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、シフト表を確認してから正確にお返事しようと考えておりまして、遅くなってしまいました。', 1, 8);

