-- 既読スルー ／ 友達 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('友達', '既読スルー', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、ご連絡を拝読しながら、ご返信が大変遅くなってしまいました。心より深くお詫び申し上げます。今後とも変わらぬご厚誼を賜りますよう、お願い申し上げます。', 4, 7),
('友達', '既読スルー', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に申し上げにくいのですが、予定を確認してからお返事しようと考えておりましたところ、失念してしまいました。', 5, 7),
('友達', '既読スルー', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、心より感謝申し上げます。誠に恐れ入りますが、拝読した直後に携帯電話の充電が切れてしまいまして、ご返信が遅れてしまいました。', 5, 4),
('友達', '既読スルー', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ながら、送信したつもりのメッセージが送れておりませんでした。大変失礼いたしました。', 6, 5),
('友達', '既読スルー', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、アルバイト中に拝読いたしまして、その後お返事を失念しておりました。', 2, 7),
('友達', '既読スルー', '丁寧', '親愛なる友へ。誠に申し訳ございません。お返事の文面を考えておりましたところ、時間が経ってしまいました。何卒ご容赦くださいませ。', 4, 7),
