-- 既読スルー ／ 家族 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ではございますが、ご連絡を拝読しながら、ご返信が大変遅くなってしまいました。心より深くお詫び申し上げます。', 1, 8),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、授業中に拝読いたしまして、その後お返事を失念しておりました。', 2, 8),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。いつも温かく見守っていただき、心より感謝申し上げます。誠に恐れ入りますが、拝読した直後に携帯電話の充電が切れてしまいまして、ご返信が遅れてしまいました。', 4, 7),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ながら、夕食が必要かどうか予定を確認してからお返事しようと考えておりました。', 2, 10),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご配慮を賜り、厚く御礼申し上げます。大変恐れ入りますが、アルバイト中に拝読いたしまして、お返事ができずにおりました。', 1, 9),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。送信したつもりのメッセージが送れておりませんでした。大変失礼いたしました。', 4, 6),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮でございますが、課題に集中しておりまして、ご返信が遅くなってしまいました。', 2, 8),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、部活動の最中でございまして、お返事ができませんでした。', 1, 7),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。大変恐縮ではございますが、通知から開いたまま閉じてしまい、ご返信を失念しておりました。', 5, 6),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。誠に恐れ入りますが、移動中で電波が悪く、お返事を送ることができませんでした。何卒ご容赦くださいませ。', 2, 7),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、友人と話し込んでおりまして、ご返信が遅れてしまいました。', 2, 6),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。平素より大変お世話になっております。誠に恐縮ながら、図書館におりましたため、お返事を控えておりました。', 2, 9),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。拝読した直後に先生に呼ばれまして、そのままお返事を忘れてしまいました。', 3, 6),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。いつも温かいお心遣いを賜り、厚く御礼申し上げます。大変恐れ入りますが、お返事を下書きしたまま、送信を失念しておりました。', 1, 7),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。日頃より大変お世話になっております。誠に恐縮ではございますが、研究室の作業中でございまして、ご返信が遅くなってしまいました。', 1, 8),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、電車の中で拝読し、降りてからお返事しようと考えておりました。', 2, 7),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。誠に申し訳ございません。疲れが出てしまいまして、拝読したまま眠ってしまいました。', 2, 7),
('家族', '既読スルー', '丁寧', '敬愛するご家族の皆様へ。いつも大変お世話になっております。誠に恐縮でございますが、頼まれた買い物の品を探しておりまして、ご返信が遅れてしまいました。', 2, 6),
