('家族', '既読スルー', 'ネタ', 'ちょっと聞いて。語尾を「！」にするか「。」にするかで悩んでた。', 6, 3),
('家族', '既読スルー', 'ネタ', 'ちょっと聞いて。指が乾燥してて画面が反応しなかった。', 10, 1),
('家族', '既読スルー', 'ネタ', 'ちょっと聞いて。スマホの画面を拭いてたら既読になってた。', 9, 1);

-- 未読スルー ／ 先生 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('先生', '未読スルー', '丁寧', '先生におかれましては、平素より格別のご指導を賜り、心より御礼申し上げます。誠に申し上げにくいことではございますが、携帯電話の充電が切れておりまして、頂戴したご連絡に気づくのが大変遅くなってしまいました。何卒ご容赦賜りますよう、伏してお願い申し上げます。', 6, 5),
('先生', '未読スルー', '丁寧', '先生、ご連絡を頂戴しながら、拝見するのが遅くなり誠に申し訳ございません。通知の設定がオフになっておりまして、気づくことができませんでした。', 7, 3),
('先生', '未読スルー', '丁寧', '先生におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、試験勉強のため携帯電話の電源を切っておりまして、ご連絡に気づきませんでした。', 1, 9),
('先生', '未読スルー', '丁寧', '先生、誠に申し訳ございません。携帯電話を自宅に忘れてしまいまして、本日一日ご連絡を拝見できずにおりました。心より深くお詫び申し上げます。', 7, 4),
('先生', '未読スルー', '丁寧', '先生におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に恐縮ではございますが、体調を崩して寝込んでおりまして、ご連絡を拝見できておりませんでした。', 1, 7),
('先生', '未読スルー', '丁寧', '先生、大変恐縮でございます。ほかの通知に紛れてしまいまして、先生からのご連絡に気づくのが遅れてしまいました。', 5, 3),
('先生', '未読スルー', '丁寧', '先生、誠に恐れ入ります。実家に帰省しておりまして、電波の弱い地域でございましたため、ご連絡を受け取ることができませんでした。', 4, 6),
('先生', '未読スルー', '丁寧', '先生におかれましては、平素より温かいご指導を賜り、心より感謝申し上げます。誠に恐縮ながら、携帯電話を修理に出しておりまして、ご連絡を拝見できずにおりました。', 2, 8),
('先生', '未読スルー', '丁寧', '先生、早朝より失礼いたします。アルバイト中は携帯電話をロッカーに預けておりまして、ご連絡に気づくのが遅くなってしまいました。', 1, 10),
('先生', '未読スルー', '丁寧', '先生、誠に申し訳ございません。アプリの更新が必要になっておりまして、メッセージを開くことができない状態でございました。', 3, 7),
('先生', '未読スルー', '丁寧', '先生におかれましては、日頃より格別のご高配を賜り、厚く御礼申し上げます。誠に恐れ入りますが、集中モードを設定したまま解除し忘れておりまして、ご連絡に気づきませんでした。', 7, 3),
('先生', '未読スルー', '丁寧', '先生、大変失礼いたしました。機種変更の手続き中でございまして、データの引き継ぎが完了しておりませんでした。', 3, 8),
('先生', '未読スルー', '丁寧', '先生、誠に恐縮でございます。部活動の合宿に参加しておりまして、携帯電話を使用できない環境におりました。', 2, 7),
('先生', '未読スルー', '丁寧', '先生におかれましては、平素より多大なるご指導を賜り、厚く御礼申し上げます。誠に申し上げにくいのですが、グループのメッセージに埋もれてしまい、ご連絡を見落としておりました。', 6, 5),
('先生', '未読スルー', '丁寧', '先生、大変申し訳ございません。機内モードを解除し忘れておりまして、ご連絡を受信できておりませんでした。', 6, 5),
('先生', '未読スルー', '丁寧', '先生、誠に恐れ入りますが、携帯電話の容量がいっぱいになっておりまして、動作が止まってしまっておりました。', 4, 7),
('先生', '未読スルー', '丁寧', '先生におかれましては、ますますご健勝のこととお慶び申し上げます。誠に恐縮ながら、通信量の制限がかかっておりまして、メッセージを受け取れておりませんでした。', 4, 8),
('先生', '未読スルー', '丁寧', '先生、大変失礼いたします。誤ってトークを非表示にしてしまっておりまして、ご連絡に気づくことができませんでした。', 3, 7),
('先生', '未読スルー', '丁寧', '先生、誠に申し訳ございません。面接のため一日中携帯電話の電源を切っておりまして、拝見するのが遅れてしまいました。', 1, 9),
('先生', '未読スルー', '丁寧', '先生におかれましては、平素より格別のご配慮を賜り、心より感謝申し上げます。誠に恐れ入りますが、携帯電話をカバンの奥にしまい込んでおりまして、ご連絡に気づきませんでした。', 3, 7);

