-- 未読スルー ／ バイト先の店長 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('バイト先の店長', '未読スルー', '丁寧', '店長におかれましては、日頃より大変お世話になっております。誠に恐れ入りますが、携帯電話の充電が切れておりまして、頂戴したご連絡に気づくのが大変遅くなってしまいました。心より深くお詫び申し上げます。', 6, 4),
('バイト先の店長', '未読スルー', '丁寧', '店長、お疲れさまでございます。ご連絡を頂戴しながら拝見が遅れ、誠に申し訳ございません。授業中は携帯電話の電源を切っておりました。', 3, 8),
('バイト先の店長', '未読スルー', '丁寧', '店長におかれましては、平素より格別のご配慮を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、通知の設定がオフになっておりまして、気づくことができませんでした。', 4, 4),
('バイト先の店長', '未読スルー', '丁寧', '店長、誠に申し訳ございません。携帯電話を自宅に忘れてしまいまして、ご連絡を拝見できずにおりました。', 5, 3),
('バイト先の店長', '未読スルー', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、試験期間中は携帯電話を別の部屋に置いておりまして、ご連絡に気づきませんでした。', 1, 9),
('バイト先の店長', '未読スルー', '丁寧', '店長におかれましては、日頃より温かいご指導を賜り、心より感謝申し上げます。誠に恐れ入りますが、体調を崩して寝込んでおりまして、ご連絡を拝見できておりませんでした。', 2, 9),
('バイト先の店長', '未読スルー', '丁寧', '店長、誠に恐縮でございます。ほかの通知に紛れてしまいまして、店長からのご連絡を見落としておりました。', 6, 4),
('バイト先の店長', '未読スルー', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、携帯電話を修理に出しておりまして、ご連絡を受け取ることができませんでした。', 2, 9),
('バイト先の店長', '未読スルー', '丁寧', '店長におかれましては、ますますご清栄のこととお慶び申し上げます。さて、誠に恐れ入りますが、家族旅行で電波の届かない場所におりました。', 3, 6),
('バイト先の店長', '未読スルー', '丁寧', '店長、大変申し訳ございません。アプリが開かない不具合が起きておりまして、メッセージを確認できない状態でございました。', 4, 4),
('バイト先の店長', '未読スルー', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、集中モードを解除し忘れておりまして、ご連絡に気づきませんでした。', 6, 5),
('バイト先の店長', '未読スルー', '丁寧', '店長におかれましては、平素より多大なるご配慮を賜り、厚く御礼申し上げます。誠に恐れ入りますが、機種変更の手続き中でございまして、データの引き継ぎが済んでおりませんでした。', 1, 7),
('バイト先の店長', '未読スルー', '丁寧', '店長、誠に申し訳ございません。部活動の合宿に参加しておりまして、携帯電話を使用できない環境におりました。', 1, 7),
('バイト先の店長', '未読スルー', '丁寧', '店長、お疲れさまでございます。大変恐れ入りますが、グループのメッセージに埋もれてしまい、ご連絡を見落としておりました。', 5, 4),
('バイト先の店長', '未読スルー', '丁寧', '店長におかれましては、日頃より格別のご高配を賜り、心より感謝申し上げます。誠に恐縮ではございますが、通信量の制限がかかっておりまして、メッセージを受け取れておりませんでした。', 3, 6),
('バイト先の店長', '未読スルー', '丁寧', '店長、誠に恐縮でございます。機内モードを解除し忘れておりまして、ご連絡を受信できておりませんでした。', 5, 3),
('バイト先の店長', '未読スルー', '丁寧', '店長、お疲れさまでございます。誠に申し上げにくいのですが、夜勤明けで眠っておりまして、ご連絡に気づくのが遅れてしまいました。', 3, 7),
('バイト先の店長', '未読スルー', '丁寧', '店長におかれましては、平素より大変お世話になっております。誠に恐れ入りますが、携帯電話の容量がいっぱいになっておりまして、動作が止まっておりました。', 3, 5),
('バイト先の店長', '未読スルー', '丁寧', '店長、大変申し訳ございません。誤ってトークの通知をミュートにしてしまっておりました。', 4, 8),
('バイト先の店長', '未読スルー', '丁寧', '店長、お疲れさまでございます。誠に恐縮ながら、携帯電話を車に置き忘れておりまして、ご連絡に気づきませんでした。', 7, 4);

