-- 未読スルー ／ 友達 ／ 丁寧
INSERT INTO gomen_excuses (aite, youken, tone, excuse, bareta, barenakatta) VALUES
('友達', '未読スルー', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、携帯電話の充電が切れておりまして、頂戴したご連絡に気づくのが大変遅くなってしまいました。心より深くお詫び申し上げます。', 6, 3),
('友達', '未読スルー', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に申し上げにくいのですが、通知の設定がオフになっておりまして、ご連絡に気づくことができませんでした。', 6, 3),
('友達', '未読スルー', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、心より感謝申し上げます。誠に恐れ入りますが、携帯電話を自宅に忘れてしまいまして、本日一日拝見できずにおりました。', 7, 5),
('友達', '未読スルー', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ながら、アルバイト中は携帯電話をロッカーに預けておりました。', 2, 8),
('友達', '未読スルー', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、試験勉強のため携帯電話の電源を切っておりました。', 3, 7),
('友達', '未読スルー', '丁寧', '親愛なる友へ。誠に申し訳ございません。体調を崩して寝込んでおりまして、ご連絡を拝見できておりませんでした。今後とも変わらぬご厚誼を賜りますよう、お願い申し上げます。', 2, 6),
('友達', '未読スルー', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、厚く御礼申し上げます。誠に恐れ入りますが、ほかの通知に紛れてしまいまして、ご連絡を見落としておりました。', 5, 4),
('友達', '未読スルー', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐縮ではございますが、旅行中で電波の不安定な場所におりました。', 3, 7),
('友達', '未読スルー', '丁寧', '親愛なる友へ。日頃より格別のご高配を賜り、心より感謝申し上げます。誠に申し上げにくいのですが、携帯電話を修理に出しておりまして、ご連絡を受け取れずにおりました。', 2, 6),
('友達', '未読スルー', '丁寧', '親愛なる友へ。誠に恐縮ではございますが、グループのメッセージに埋もれてしまいまして、気づくのが遅れてしまいました。', 7, 5),
('友達', '未読スルー', '丁寧', '親愛なる友へ。平素より大変お世話になっております。誠に恐れ入りますが、集中モードを解除し忘れておりまして、通知が届いておりませんでした。', 8, 4),
('友達', '未読スルー', '丁寧', '親愛なる友へ。いつも格別のお心遣いを賜り、厚く御礼申し上げます。大変恐縮ながら、機種変更の手続き中でございまして、データの引き継ぎが済んでおりませんでした。', 1, 9),
('友達', '未読スルー', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。誠に恐縮でございますが、部活動の合宿に参加しておりまして、携帯電話を使用できない環境におりました。', 1, 8),
('友達', '未読スルー', '丁寧', '親愛なる友へ。平素より格別のご厚情を賜り、心より御礼申し上げます。誠に申し上げにくいのですが、通信量の制限がかかっておりまして、メッセージを受け取れておりませんでした。', 5, 7),
('友達', '未読スルー', '丁寧', '親愛なる友へ。誠に恐れ入りますが、機内モードを解除し忘れておりまして、ご連絡を受信できておりませんでした。', 8, 4),
('友達', '未読スルー', '丁寧', '親愛なる友へ。いつも温かいお付き合いを賜り、厚く御礼申し上げます。誠に恐縮ながら、誤ってトークの通知をミュートにしてしまっておりました。', 4, 7),
('友達', '未読スルー', '丁寧', '親愛なる友へ。日頃より大変お世話になっております。大変恐れ入りますが、ライブ会場におりまして、携帯電話を見ることができませんでした。', 3, 6),
('友達', '未読スルー', '丁寧', '親愛なる友へ。平素より格別のご高配を賜り、厚く御礼申し上げます。誠に恐縮ではございますが、携帯電話をカバンの奥にしまい込んでおりました。', 3, 7),
('友達', '未読スルー', '丁寧', '親愛なる友へ。誠に申し訳ございません。早めに休んでおりまして、ご連絡に気づいたのが翌朝でございました。', 3, 7),
('友達', '未読スルー', '丁寧', '親愛なる友へ。いつも大変お世話になっております。誠に恐れ入りますが、携帯電話の容量がいっぱいになっておりまして、動作が止まっておりました。今後とも末永くよろしくお願い申し上げます。', 2, 7);

